INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11219, 'frFR', 'Les enfants de la Horde ont besoin de vous ! Ne les abandonnez pas !', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(16, 'frFR', 'Merci, $N ! Et revenez si vous voulez refaire affaire.', 0),
(22, 'frFR', 'Ils sont juste comme il faut, $N ! Merci beaucoup. Saldean le fermier et moi-même allons faire un festin ce soir. Et tenez, un petit quelque chose pour vous, pour votre peine. Vous ne pensiez tout de même pas que j''allais laisser un $C comme vous mourir de faim ?', 0),
(23, 'frFR', 'Ha, la patte d''Ursangous ! Votre talent est impressionnant, $C ; on dit l''animal meurtrier. Le croissant sur la patte prouve avec certitude qu''il a été entraîné par les elfes de la nuit qui rôdent dans Orneval. Ursangous est... était un des plus puissants ours dans ces parages. Avoir battu cette bête est une preuve de votre volonté et de votre résolution.$B$BVos ancêtres seraient fiers !', 0),
(27, 'frFR', 'Salutations, jeune $C ; le temps est venu pour vous d''apprendre votre forme aquatique. Elle vous permettra de vous déplacer dans l''eau librement et indéfiniment. Vous trouverez cela utile... mais c''est quelque chose qui doit se mériter avant de pouvoir le maîtriser.$B$BVous allez avoir à passer deux tests. Le premier va tester votre habileté à travailler sous l''eau en situation de stress. Le second va tester votre capacité à comprendre les différents aspects de la forme elle-même.$B$BPréparez-vous, le moment de vous tester est venu.', 0),
(28, 'frFR', 'Bien, il semble qu''un $C de plus ait réussi à passer l''épreuve du lac ! Bien joué, jeune $C - bien joué.$B$BComme je l''ai dit, mon nom est Tajarri. C''est mon devoir et un privilège d''être un Gardien de Reflet-de-Lune, et tout spécialement de ce sanctuaire. Le Gardien Remulos guide le Cercle cénarien pour préserver la nature et l''équilibre, son sanctuaire en est la démonstration. Il prouve l''importance de ce lieu dans le Cercle.', 0),
(29, 'frFR', 'Bien, il semble qu''un $C de plus ait réussi à passer l''épreuve du lac ! Bien joué, jeune $C - bien joué.$B$BComme je l''ai dit, mon nom est Tajarri. C''est mon devoir et un privilège d''être un Gardien de Reflet-de-Lune, et tout spécialement de ce sanctuaire. Le Gardien Remulos guide le Cercle cénarien pour préserver la nature et l''équilibre, son sanctuaire en est la démonstration. Il prouve l''importance de ce lieu dans le Cercle.', 0),
(30, 'frFR', 'Vous avez réussi l''épreuve du lion de mer, $N, félicitations.$B$BChacune des tâches nécessaires pour acquérir le pendentif souligne que l''agilité et l''endurance doivent agir en harmonie lorsque l''on se trouve sous l''eau. L''une ne peut pas exister sans l''autre, et les deux ne peuvent être sans votre détermination à comprendre les différents aspects du lion de mer.$B$BRappelez-vous bien ces leçons, et comptez sur elles une fois que vous aurez obtenu votre forme aquatique.', 0),
(48, 'frFR', 'Hic ! Oh ! Oh !', 0),
(49, 'frFR', 'Hic ! Oh ! Oh !', 0),
(50, 'frFR', 'Hic ! Oh ! Oh !', 0),
(51, 'frFR', 'Hic ! Oh ! Oh !', 0),
(53, 'frFR', 'Vieilli en fût, et par le charbon filtré$BIl passe sur vos lèvres, pour ensuite votre esprit transpercer.$BMaintenant buvons, pour vous un toast portons$BEt tant que vous êtes là, un toast pour Tristevin Tonnebière aussi portons !', 0),
(98, 'frFR', 'Je sais, $N : Stalvan est mort. J''ai senti une onde d''espoir passer sur la forêt maudite. Le bois de la Pénombre est débarrassé de sa soif de sang. Ma joie est toutefois teintée de tristesse, quand je pense à tous ces pauvres gens qui sont morts par sa faute. Néanmoins, vous êtes un brave $C.', 0),
(103, 'frFR', 'Louée soit la Lumière, brave $C ! Les récifs de la côte de l''Ouest seront signalés aux navires, merci pour votre dur labeur. De nombreuses vies seront sauvées tant que brillera cette flamme.$B$BJe suis mort en vain sur cette côte. Je souhaite que personne ne connaisse le même sort que moi.', 0),
(113, 'frFR', 'Merci de m''avoir apporté le rapport, géomètre novice $N ; voici pour vos services à la Compagnie des Eaux de Gadgetzan.$B$BJe ne suis généralement pas très chaud pour laisser filtrer des informations sans contrepartie, mais je connais Pestlezugg depuis des années. S''il recommande que ce rapport puisse être lu par tout le monde, alors qu''il en soit ainsi. Attendez un moment que je vous fasse une copie.', 0),
(134, 'frFR', 'Béni soit le Néc… enfin béni soyez-vous, $N ! Vous avez largement mérité votre récompense.$B$BHa ! Heureuses ! Les nuits vont être heureuses !', 0),
(151, 'frFR', 'Oh merci, merci, $N ! La vieille Blanchy va être si heureuse !', 0),
(169, 'frFR', 'Fantastique, $N ! Gath''Ilzogg a conduit ces brutes au combat, massacrant de nombreux humains innocents. Nous avons notre revanche. Pour le royaume de Hurlevent, c''est le premier pas vers la reprise du Donjon !', 0),
(188, 'frFR', 'Je ne peux que m''incliner. Vous êtes un maître-chasseur de tigres, $N !', 0),
(208, 'frFR', 'Merveilleux ! Hourra ! Bravo à vous, $N ! Vous avez réussi là où tant d''autres ont échoué.$B$BC''est pour moi un grand honneur de vous compter parmi mes camarades. Personne ne peut remettre en doute votre talent dans l''art de la chasse !$B$BBravo à vous ! Bravo !', 0),
(212, 'frFR', 'Ah, ce sera parfait. Merci, merci beaucoup !$B$BÀ présent, si vous voulez bien m''excuser, ce cuissot a besoin d''être débité, cuisiné et dressé pour le banquet.', 0),
(214, 'frFR', 'Bien joué, $N ! Au nom de la milice du peuple, je salue vos efforts. Bientôt, avec l''aide de gens courageux tels que vous, nous rendrons cette terre au peuple.', 0),
(235, 'frFR', 'Bienvenue à la nouvelle frontière, $N. Orneval est une terre d''opportunités, où un jeune $C comme vous peut avoir de nombreuses chances de prouver sa vaillance. Faites le tour de l''Avant-poste et n''oubliez pas de voyager jusqu''à la Grève de Zoram, étant donné que la Horde a aussi un autre Avant-poste, là-bas.$B$BVotre présence ici me dit que vous êtes venu pour en apprendre plus sur l''art de la chasse. Écoutez attentivement, et je partagerai volontiers avec vous le savoir qui vous manque.', 0),
(249, 'frFR', 'Vous avez bien œuvré, $N. En battant Morganth le démoniste, vous avez mis Hurlevent à l''abri d''un grave danger.$B$BJe vous remets, en toute humilité, cette récompense. Avec cela, je vous souhaiterais la paix, si ces temps troublés permettaient un tel vœu.$B$BMais je vous souhaite une bonne fortune dans vos futures épreuves, et la victoire dans les combats qui vous attendent.', 0),
(272, 'frFR', 'Vous avez réussi l''épreuve du lion de mer, $N, félicitations.$B$BChacune des tâches pour acquérir le pendentif montre que l''agilité et l''endurance doivent agir en harmonie lorsque l''on se trouve sous l''eau. L''une ne peut pas exister sans l''autre, et les deux ne peuvent être sans votre détermination à comprendre les différents aspects du lion de mer.$B$BRappelez-vous bien ces leçons, et comptez sur elles une fois que vous aurez obtenu votre forme aquatique.', 0),
(278, 'frFR', 'Juste à temps, $N !', 0),
(279, 'frFR', 'Ah ! Bon travail, $N !$B$BAcceptez ceci en paiement pour avoir honoré votre contrat avec la marine marchande.', 0),
(308, 'frFR', 'Pour moi ? Vous êtes le symbole de l''héroïsme, $N !', 0),
(311, 'frFR', 'Pas mal, $N ! Avez-vous eu du mal à passer malgré leur garde ?$B$BPeu importe : mille mercis ! Et si vous avez un jour besoin d''hommes vaillants et énergiques, n''oubliez pas les Barleybrew !', 0),
(795, 'frFR', 'Vous placez les Pierres runiques dans leur alcôves respectives et soudain un violent grondement fait trembler la terre tandis que le Sceau se brise.', 0),
(822, 'frFR', 'Ha ha ! Je savais que vous ne résisteriez pas à l’envie de goûter ce mélange. Revenez quand vous voulez si vous en souhaitez encore, $N. Apportez-moi simplement les ingrédients nécessaires.', 0),
(849, 'frFR', 'Vous avez œuvré à merveille, $N ! Puissiez-vous être révéré à Thunder Bluff comme protecteur des terres sacrées des taurens et champion de la tribu perdue.', 0),
(862, 'frFR', 'D''ordinaire je n''aime pas manger ces rongeurs quand ils sont si… si… verts. J''aime les laisser pourrir quelques semaines pour que le fumet ressorte vraiment. Mais vous avez l''air si affamé. Laissez-moi vous faire un bon brouet de rat. Et c''est parti...$B$BTenez, voilà pour vous.', 0),
(864, 'frFR', 'Je vais immédiatement analyser ces données. Peut-être que la folie de Keever s''avérera être mon génie après tout.$B$BQuant à vous… vous m''êtes utile, et je récompense très bien ceux qui restent utiles. Prenez cet objet, cette pièce, et plus important encore, mes remerciements qui les accompagnent.$B$BRevenez me voir de temps en temps - je mise sur le fait que notre collaboration sur ce projet n''est pas terminée.', 0),
(876, 'frFR', 'Ah ! Bon travail, $N ! Très bon travail… Je n''étais pas sûr que vous en seriez capable, mais vous avez montré que vous êtes un coupe-gorge remarquable. Merci encore pour nous aider à soigner l''épidémie harpie. Voici votre récompense, utilisez-la bien.', 0),
(889, 'frFR', 'Bien. Que l''esprit d''Agammagan vous guide, $N. Revenez me voir si vous désirez davantage de la magie d''Agammagan.', 0),
(897, 'frFR', 'Je ne peux rien dire de la nature de cette bête, car son esprit s''est enfui. Mais comme vous l''aviez supposé, elle n''appartient pas aux Tarides. Je crains que cela n’annonce un avenir bien lugubre pour notre peuple… Mais pour l''heure, préparez-vous, et espérons que le temps éclaircisse le mystère posé par l''existence de cette créature.', 0),
(905, 'frFR', 'Ainsi vous vous êtes rendu aux nids et vous y avez placé les plumes de vos proies. Cela a nécessité beaucoup de courage, c''est certain.$B$BVous sentez-vous un peu plus fort, $N ? Car il me semble que vous l''êtes plus que lors de votre première visite. Je crois que les Tarides accomplissent leur œuvre.', 0),
(920, 'frFR', 'Ah $N ! J''espérais bien que vous seriez prompt à répondre à mes appels. J''aimerais vous confier une importante tâche.', 0),
(936, 'frFR', 'Salutations, $C. Je suis heureux de voir que l''idée de nous prêter main-forte vous intéresse. Il y a beaucoup à faire, et ce ne serait pas vous rendre service que de vous dire que ce travail ne comporte aucun danger. J''espère que cela ne va pas vous effrayer... Mais en vous regardant, il me semble comprendre que vous avez déjà eu à faire au danger.', 0),
(938, 'frFR', 'Oh merci $N ! J''ai eu tellement peur de ne plus jamais revoir Brume. J’ignorais quel sort était réservé à ma fidèle camarade. Je vous dois plus que vous ne pourriez imaginer, et vous avez ma reconnaissance éternelle.', 0),
(943, 'frFR', 'Plus que parfait, $N !$B$BÀ présent voyons si je peux utiliser la pierre pour découvrir les pouvoirs des fossiles.', 0),
(957, 'frFR', 'Je suis libre, $N ! Je peux à présent voir de mes propres yeux les changements qui sont survenus dans notre monde… Je n''en ai connu que des fragments, des morceaux. Quand je pense que la dernière fois que j''ai marché librement, le Puits était toujours debout et que les Bien-nés étaient à la cour avec Azshara, notre reine bien-aimée...$B$BJe sens que mon geôlier, mon ancien maître, Athrikus, est toujours en vie... Déjà, mes sentiments de désespoir laissent place à des projets de vengeance.', 0),
(995, 'frFR', '$N ! Je suis heureux de voir que vous avez réussi. En aidant Volcor, vous m''avez rendu la foi : nous surmonterons les défis qui nous attendent à Sombrivage et au-delà.', 0),
(996, 'frFR', 'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s''épanouir en une plante vibrante de santé.', 0),
(998, 'frFR', 'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Il commence immédiatement à se défaire de sa forme souillée pour s''épanouir en une plante vibrante de santé.', 0),
(1000, 'frFR', 'Salutations, $C.$B$BJe me réjouis de voir que des personnes telles que vous prennent de l''intérêt au bien-être de la nature. Vos faits d''armes sont parvenus jusqu''à mes oreilles, et je vous souhaite la bienvenue. De vous voir ainsi devant moi ne me laisse plus aucun doute : le Cercle cénarien vient de recevoir l''aide dont il avait besoin.$B$BNotre intelligence avec le Cercle cénarien de Reflet-de-Lune transcende tout conflit racial ou politique. Rappelez-vous que vous travaillez au nom du Cercle, et je ne crois pas me tromper en pensant que vous le ferez bien.', 0),
(1004, 'frFR', 'Salutations, $C.$B$BJe me réjouis de voir que des personnes telles que vous prennent de l''intérêt au bien-être de la nature. Vos faits d''armes sont parvenus jusqu''à mes oreilles, et je vous souhaite la bienvenue. De vous voir ainsi devant moi ne me laisse plus aucun doute : le Cercle cénarien vient de recevoir l''aide dont il avait besoin.$B$BNotre intelligence avec le Cercle cénarien de Reflet-de-Lune transcende tout conflit racial ou politique. Rappelez-vous que vous travaillez au nom du Cercle, et je ne crois pas me tromper en pensant que vous le ferez bien.', 0),
(1007, 'frFR', 'Vous l''avez ! Merci, $N !$B$BLa vieille cité de Zoram renferme de nombreux secrets et cette statuette est peut-être la clé qui nous permettra de les découvrir.', 0),
(1009, 'frFR', 'Vous avez trouvé l''Anneau ! Merci, $N. Je vous en prie, acceptez ceci en paiement et sachez que ce que vous avez fait restera gravé pour toujours dans ma mémoire.', 0),
(1018, 'frFR', 'Salutations, $C.$B$BJe me réjouis de voir que des personnes telles que vous prennent de l''intérêt au bien-être de la nature. Vos faits d''armes sont parvenus jusqu''à mes oreilles, et je vous souhaite la bienvenue. De vous voir ainsi devant moi ne me laisse plus aucun doute : le Cercle cénarien vient de recevoir l''aide dont il avait besoin.$B$BNotre intelligence avec le Cercle cénarien de Reflet-de-Lune transcende tout conflit racial ou politique. Rappelez-vous que vous travaillez au nom du Cercle, et je ne crois pas me tromper en pensant que vous le ferez bien.', 0),
(1019, 'frFR', 'Qu''est-ce qui vous fait penser que je veux être enquiquiné par des gens de votre acabit, $C ? Allons, j''arrête mes importantes activités quotidiennes pour vous aider à localiser un truc-machin quelque part. Bien entendu, le bien de Darnassus - non, de tout Teldrassil - passe après la récupération d''un nouveau bidule pour votre collection.$B$BCes idiots de Reflet-de-Lune me font déjà perdre mon temps avec leurs demandes d''aide, et maintenant, il faut que je supporte ça ?', 0),
(1027, 'frFR', 'Vous avez trouvé le dernier morceau ? C''est merveilleux pour vous... et pour Raene.$B$BJe pense qu''il faut maintenant réparer, n''est-ce pas ?', 0),
(1047, 'frFR', 'Qu''est-ce qui vous fait penser que je veux être enquiquiné par des gens de votre acabit, $C ? Allons, j''arrête mes importantes activités quotidiennes pour vous aider à localiser un truc-machin quelque part. Bien entendu, le bien de Darnassus - non, de tout Teldrassil - passe après la récupération d''un nouveau bidule pour votre collection.$B$BCes idiots de Reflet-de-Lune me font déjà perdre mon temps avec leurs demandes d''aide, et maintenant, il faut que je supporte ça ?', 0),
(1079, 'frFR', 'Vraiment ahurissant ! C''est un grand coup porté à la KapitalRisk.$B$BNous allons pouvoir trouver les faiblesses de leurs machines, mais aussi intégrer leurs concepts dans nos propres créations. C''est un grand jour, vraiment.', 0),
(1080, 'frFR', 'Incroyable, $N ! Kaela et les Sentinelles seront si heureuses. Avec vos compétences et mes créations, rien ne peut nous arrêter.', 0),
(1088, 'frFR', 'J''ai rencontré Ordanus une fois, il y a longtemps. Il possédait l''arrogance de sa race, se considérant même supérieur aux Bien-nés.$B$BSa tête ne monte plus aussi haut, à présent, n''est-ce pas, $N ?$B$BJe vous ai promis une récompense, et vous l''aurez. Regardez.', 0),
(1101, 'frFR', 'La mégère a été enterrée. Voilà des nouvelles fantastiques, $N.$B$BEn ces temps de danger, il est rafraîchissant de voir quelqu''un d''aussi brave que vous.$B$BPuisque les laquais de Trancheflanc ont été éliminés, nos études dans ce secteur vont pouvoir se poursuivre. Peut-être que nous pouvons à présent approfondir notre connaissance du mal qui a corrompu le lieu où Agammagan s''est éteint.$B$BJ''ai bien peur cependant que la réponse à cette question ne repose également dans la trahison...', 0),
(1104, 'frFR', 'Très bien ! Ce venin va parfaitement faire l''affaire ! Merci, $N !$B$BMaintenant je n''ai plus qu''à le faire bouillir, lui ajouter un negacatalyste, puis… Ah ! Où sont mes notes ?', 0),
(1107, 'frFR', 'Merci, $N ! Mon composite sera fin prêt après pulvérisation et mélange avec quelques autres composants. Et après ça, le chariot sera à l''abri de sa propre vitesse.$B$BA l''abri, tant qu''il ne fonce pas dans quelque chose…', 0),
(1113, 'frFR', 'Mais quelle effusion de sang, $N ! Vos efforts ont été plus que récompensés !', 0),
(1116, 'frFR', 'Eh bien, voyez-vous ça ! Vous avez trouvé la Poussière de rêve !$B$BEt les marécages, c''était comment, vous avez aimé, $N ?$B$BCe n''est pas facile de trouver un repas chaud dans le coin, pas vrai ?', 0),
(1119, 'frFR', 'Merveilleux ! Fizzlebub y est parvenu ! Je m''en souviendrai la prochaine fois que je le verrai.$B$BMerci, $N. Vous faites un travail formidable, et il se peut que nous nous fassions pas mal d''argent avec ça…', 0),
(1122, 'frFR', 'Ça raconte que la Bière du sot a été un succès. Voilà de bonnes nouvelles !$B$BSi plus tard vous en voulez davantage, alors faites-le-moi savoir et je vous demanderai de récupérer plus de Mixtures de Zanzil.', 0),
(1131, 'frFR', 'En tuant cet abominable Broie-l''acier, vous avez débarrassé les Mille pointes d''un terrible fléau.$B$BEt ceci, $N, est votre leçon pour aujourd''hui.', 0),
(1133, 'frFR', 'Vous êtes ici pour offrir vos services à l''Alliance, $N ? Nous les acceptons avec gratitude, car même s''il lui reste sa beauté la forêt d’Orneval n''est plus aussi paisible qu''autrefois.', 0),
(1139, 'frFR', '<Le Conseiller Belgrum hoche la tête d''un air surpris lorsque vous lui tendez la pierre. >$B$B$N, c''est ahurissant ! Je dois la faire porter aux mages du roi aussi vite que possible. Ils voudront l''analyser pour vérifier la véracité de la légende ! Mais c''est un autre sujet. Vous avez apporté à notre peuple une aide plus grande que tout ce que nous aurions pu espérer. Merci !', 0),
(1142, 'frFR', 'Non !$B$BCe n''est pas juste ! Monde cruel et intolérable !$B$BJe devrai à présent porter ce fardeau de douleur ; mais je ne laisserai pas le travail de Heralath partir avec lui.$B$BVous avez montré du courage lors de votre voyage par ces contrées si dangereuses, $N. Maintenant, laissez-moi, je vous en prie.$B$BC''est dans la solitude que je veux pleurer son départ.', 0),
(1147, 'frFR', 'Ah ! Cet ichor qui vous couvre vous embellit, $N ! Et cela vous donne une odeur... Une odeur... Qui empeste ! Ne vous approchez pas trop des kodos : vous provoqueriez une cavalcade ou vous les mettriez en chaleur.$B$BJe pense que mes compagnons seront d''accord pour admettre que cette odeur à elle seule est la preuve que vous avez pris part au combat contre ces insectes. Merci $N.', 0),
(1148, 'frFR', 'Ahh, tu as vu Moktar récemment ? Il veille toujours sur moi. Je suis désolé d''apprendre qu''il passe son temps à surveiller son petit groupe de guerre au lieu de se battre, mais je suis sûr qu''il prend beaucoup de plaisir à tuer des membres de la Ligue des explorateurs.$B$BVous avez bien fait de m''apporter ces spécimens, $N. Avec les œufs que nous avons trouvés dans le champ des géants, ils devraient me permettre de mieux comprendre ce que sont ces insectes et ce qu''ils veulent.', 0),
(1153, 'frFR', 'Un bel échantillon, $N ! Bel échantillon, en vérité !$B$BCes voyageurs ne pourront plus me regarder de haut avec leur découverte, maintenant que vous avez réussi.$B$BIl faut que je me mette au travail immédiatement. S''il est assez résistant, j''enverrai au Chef de guerre une arme forgée dans ce métal pour lui montrer notre réussite.$B$BJe n''oublierai pas votre aide, $C.', 0),
(1176, 'frFR', 'Magnifique ! Je peux mettre mon équipe immédiatement sur ce projet ! Merci, $N !', 0),
(1186, 'frFR', 'C''est vous qui avez donné un coup de main à Pozzik, c''est ça, $N ? J''ai été comme vous, moi aussi, à courir autour des ateliers, à faire tous les petits boulots que les mécaniciens voulaient bien me confier !$B$BEt maintenant regardez-moi ! Je suis l''extraordinaire pilote de l''équipe de course des gobelins !', 0),
(1205, 'frFR', 'Très bien, $N.$B$BJe suis sûr que cette chasse n''a pas été facile, mais je suis heureux de savoir que les souffrances de cette bête ont enfin cessé.', 0),
(1221, 'frFR', 'Excellent, vous les avez ! Je peux les vendre un bon prix à mes clients !$B$BMerci pour la livraison, $N ! Vous êtes quelqu''un de précieux.', 0),
(1242, 'frFR', 'Je vous demande pardon, une lettre pour moi ? Ça par exemple... Ce n''est pas souvent qu''on vous livre autre chose qu''une caisse ou un baril quand vous ne faites rien d''autre que travailler. Voyons de quoi cela parle.$B$B<Elling vous regarde en ouvrant la lettre. >$B$BVous me semblez un peu tendu, vous allez bien, $N ?', 0),
(1248, 'frFR', 'Bienvenue, bienvenue, bienvenue, $N ! C''est gentil de votre part de vous joindre à nous. Peut-être une bière ? Ou du mouton ?$B$BDites-nous ce dont vous avez envie et je ferai en sorte que votre souhait se réalise.$B$BHmm ? Qu''est-ce que cela ? Trias ? Baissez la voix, je vous en prie. Il s''agit d''un sujet qui ne concerne pas le reste de la taverne.', 0),
(1258, 'frFR', 'Ce sont des spécimens magnifiques, $N ! Les carapaces sont parfaites et les chairs sont tendres et roses. Le sang des plus grands chefs cuisiniers coule dans vos veines, j''en suis sûr !', 0),
(1267, 'frFR', 'Tout d''abord, permettez-moi de vous remercier pour tout ce que vous avez fait, $N. Vous êtes un don du ciel pour mon peuple et celui de Hurlevent. J’aurais préféré faire votre connaissance dans d’autres circonstances.$B$BComprenez également que je ne peux reconnaître officiellement vos mérites, mais sachez que ceux-ci sont grandement appréciés.$B$BLorsque vous reviendrez à Theramore, venez me voir et je vous informerai de la situation.$B$BMerci encore, $N.', 0),
(1369, 'frFR', 'Vous avez les larmes ! Maintenant les Gelkis vont savoir que Theradras ne les aidera pas. Elle ne pleurera pas lorsque nous allons les écraser ! Les Magram régneront !$B$BVous êtes intelligent de nous aider, $N. Nous sommes les plus forts.', 0),
(1371, 'frFR', 'Oui, c''est ça que j''avais ! Je vais le faire bouger. Ça me fait tellement rire !', 0),
(1375, 'frFR', 'Le khan Shaka est mort ! Je vais placer sa tête sur une pique et la garder avec moi afin que Shaka puisse voir la puissance des Magram !', 0),
(1381, 'frFR', 'Le khan Hratha est mort ! À présent, les Magram sont les plus forts des centaures ! Nous écraserons les autres et règnerons sur Désolace !$B$BNous nous souviendrons de vous, $N.', 0),
(1383, 'frFR', 'Splendide, $N ! Et juste à temps, en plus. D''après ce que me dit Zraedus, l''infiltrateur s''est remis de ses blessures et est prêt à être interrogé par les orcs.$B$BDonnez-moi simplement un moment pour que je prépare le pois… je veux dire, le sérum de vérité.', 0),
(1385, 'frFR', 'Beaucoup de Gelkis sont tombés devant vous. J''aime ça. Peut-être pouvez-vous faire plus de choses que j''aime. Peut-être que vous et les centaures Magram peuvent être amis.', 0),
(1386, 'frFR', 'Les centaures Kolkar ont peur de vous maintenant. J''espère que vous avez ri en les tuant. C''est meilleur de rire en tuant, car l''ennemi voit qu''il est faible.', 0),
(1388, 'frFR', 'Je savais que le vieux Faustin arriverait à quelque chose de bon ! Vous avez été d''une aide extraordinaire, c''est certain.$B$BÀ présent parlons affaires, voulez-vous ?', 0),
(1391, 'frFR', 'Une boisson, pour moi ? Comme c''est aimable. Cela fait des jours qu''ils ne m''ont pas permis de me désaltérer. Laissez-moi boire ça, et alors je vous dirai ce que j''ai appris…', 0),
(1394, 'frFR', 'Ah, $N. Cela fait longtemps que tu n''es pas entré dans ma maison. Il semble que de nombreuses lunes se soient écoulées depuis que tu as fait le premier saut qui t''a mis sur la voie.$B$BEt maintenant, tu me reviens plus fort que tu ne l''étais... plus éclairé. Cela me fait plaisir. Et tu devrais être récompensé à juste titre pour avoir suivi mes tests jusqu''au bout.', 0),
(1448, 'frFR', 'Le temple d''Atal''Hakkar a été englouti sous la surface du Bassin des larmes ? Et il est cerné de rejetons du Vol vert ?$B$BVoilà une découverte ahurissante, $C ! Mais de toute évidence, quelque chose s''est extrêmement mal déroulé.', 0),
(1449, 'frFR', 'Que voulez-vous, fiston ? Vous ne voyez pas qu''il y a des problèmes qui requièrent mon attention ici ? Qui a le temps de rester à jacasser avec un $R ?$B$BIl y a des trolls qui sortent d''un peu partout. Magnez-vous !', 0),
(1452, 'frFR', 'Je vois que vous n''avez pas eu de problèmes pour me dénicher ce dont j''avais besoin ! Vous parlez d''une besogne que vous avez dû faire dans la lointaine Kalimdor.$B$BÇa va me prendre du temps pour extraire la substantifique moelle de ces gésiers et de ces foies.$B$BAlors je pourrai me servir une bonne vieille boisson qui arrache et vous dire enfin c''que vous voulez savoir.$B$BHic !$B$BÇa m''fait trembler rien qu''de repenser à c''vieux marais.$B$BLaissez-moi préparer le bébé en vitesse.', 0),
(1456, 'frFR', 'C''est parfait, $N ! Vous avez trouvé les possessions de Karnitol !$B$BCes fichus nagas, toujours à créer des problèmes. Je préférerais passer ma vie à faire la guerre à la Horde plutôt que d''avoir à combattre leur race. Vous avez rendu un grand service aux Récupérateurs.', 0),
(1459, 'frFR', 'Votre soutien ici est une bénédiction, $N. Vous divisez au moins par deux le temps que j’ai à passer en Désolace. Avec votre aide, je serai de retour à Ironforge en un rien de temps et je pourrai enfin y réchauffer mes pieds.$B$BUne fois que nous nous serons occupés de cette liste, et que je serai rentré, venez me voir, je vous paierai une bonne bière, ça sera la moindre des choses.$B$BMais en attendant, occupons-nous du reste de ces réactifs.', 0),
(1466, 'frFR', 'Honnêtement ? Je ne l''aurais pas cru possible. Vous êtes incroyable, $N ! Combattre des démons pour une simple expérience de mage, et revenir en un seul morceau, c''est un beau début ! Bon travail !$B$BJe vais personnellement vous recommander à Roetten lorsque je rentrerai à Ironforge.', 0),
(1467, 'frFR', 'Ah ! La caisse pour Leftwitch, de Désolace. Excellent. J''apprécie le travail, et votre à-propos, $C. Heureux de vous avoir à bord pour au moins ce petit travail.$B$BJ''ai votre paie juste ici. Que Récupérateurs SA reste réputée pour bien payer une bonne semaine de travail !', 0),
(1469, 'frFR', 'Rhapsody Croquejarret ! C''est ça… Comment j’ai pu oublier un tel nom ?$B$BAlors il était au courant depuis tout ce temps pour le temple englouti ? Eh bien, cela aurait pu vous épargner de la marche à pied.$B$BMais cet artefact atal''ai ! Quelle trouvaille !', 0),
(1475, 'frFR', 'Les tablettes atal''ai ! Merci, $N !$B$BUne fois que je les aurai remises à la Ligue des Explorateurs, nos noms seront gravés côte à côte dans l''histoire. Vous avez aidé un vieux nain à remplir son dernier devoir dans la vie. Je vous en suis éternellement reconnaissant.', 0),
(1514, 'frFR', 'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s''épanouir en une plante vibrante de santé.', 0),
(1524, 'frFR', 'Ah, je me suis trompé, $N ! Toutes mes excuses. Je n''avais pas remarqué que vous aviez la Torche. Je suis ravi de faire votre connaissance.$B$BBeaucoup d''aventuriers arrivent ici à la recherche d’un trésor perdu ou de créatures mystiques à tuer, et s’en retournent à la vue d’un autel apparemment vide. Mais nous savons que ce n''est pas le cas, n''est-ce pas, $N ?$B$BCet autel cache son grand secret aux simples membres de la Horde. Pour nous, il est sacré.', 0),
(1532, 'frFR', 'Pour le moment, je vais vous donner de quoi focaliser vos sorts et appeler les esprits de l''air. Prenez ce totem, et quand vous serez prêt revenez me voir pour approfondir votre enseignement.', 0),
(1578, 'frFR', 'Ah ! Toutes mes excuses ! Je ne savais pas que vous étiez là pour nous aider à équiper nos troupes. Ce que vous avez fait nous sera d''un grand secours !$B$BVoici les plans pour un type d''armure. J''espère qu''ils vous seront utiles.', 0),
(1582, 'frFR', 'Oui, ce sont de bonnes pièces. Vous avez une main habile et le sens du détail. Votre avenir en tant que maroquinier est prometteur.$B$BTenez, $N. Je vais vous montrer le patron du gilet Moonglow.', 0),
(1618, 'frFR', 'Merci, $N ! Ceci va énormément m''aider. Avec les orcs de Blackrock qui attaquent le donjon de Guet-de-pierre et les gnolls des Carmines qui guettent dans les collines au nord, je suis toujours en train de réparer des armures et de fabriquer des armes.$B$BLe stock que vous m''avez apporté va me donner un moment de répit. Je vais avoir suffisamment de temps pour vous apprendre quelque chose...', 0),
(1685, 'frFR', 'Enfin vous vous montrez ! J''aurais peut-être dû envoyer quelqu''un de plus compétent que Remen pour vous trouver.$B$BCe n''est pas grave.$B$BCela fait trop longtemps que vous n''avez pas eu d''entraînement, et un $C sans entraînement ne garde pas la tête sur ses épaules très longtemps.', 0),
(1691, 'frFR', 'Joli travail, $N... Joli ! Vous avez réduit le nombre des nomades à un point qui nous permet de les affronter !$B$BParlez à l''Opérateur du robinet Trimballot ici ; il donne une récompense pour chaque outre de Bat-le-désert prise lors de votre combat contre les nomades !', 0),
(1819, 'frFR', 'Bien joué, $N. Ulag n''était pas une piétaille du Fléau. Vous avez montré aux Gardes noirs, et donc à la Dame noire, que vous êtes un $C compétent et résolu, et digne de remplir d''autres missions.', 0),
(1820, 'frFR', 'Oui, c''est vrai ! J''ai besoin des talents d’un $C. J''ai des moyens modestes, mais la tâche à accomplir m''aidera autant qu''elle aidera la cause des Réprouvés. Faites-le, et votre récompense sera double.', 0),
(1821, 'frFR', 'Ah ! Vous les avez trouvées ! Maintenant le peu d''honneur et de mémoire qu''il restait est sorti des terres maudites des Agamand. Cette famille n''est plus rien à présent !', 0),
(1878, 'frFR', 'Excellent : plus nous récupérons d''outres, moins nous risquons le désastre ! Rapportez-en encore, et je vous récompenserai pour chaque lot de cinq outres que vous rapporterez.', 0),
(1918, 'frFR', 'Vous trouvez une boule d''eau sale et décidez de me l''amener ? Vous me prenez pour qui, le Cercle terrestre, ou quoi ?$B$BEn fait, ça me donne une idée... peut-être que vous aurez besoin du Cercle terrestre pour ça. Je veux dire, si ça peut aider à éclaircir la situation au lac pour de bon, je suis à fond pour.$B$BVous savez qui sont les gens du Cercle terrestre, $N ?', 0),
(1938, 'frFR', 'J''ai eu peur que Morganth n''ait caché le livre ailleurs, ou qu''il n’ait trouvé un moyen de l''ouvrir et de le lire.$B$BC''est rassurant de constater qu''il ne l''a pas fait et que les scellés que nous avions posés sur l’ouvrage ne sont pas brisés.', 0),
(2199, 'frFR', 'Vous êtes quelqu''un de bien. Je me fiche de ce que peuvent dire les autres... C''est une blague ! Non, sérieusement, merci.$B$BCe Collier que vous avez trouvé est l''une de mes plus belles réussites, mais il lui manque les trois Gemmes pour retrouver son pouvoir magique. Je l''avais fait pour un paladin, il y a quelque temps. Il s''était fixé comme mission de nettoyer la "contamination maléfique" d''un site d''excavation nommé Uldaman, dans les Terres ingrates.$B$BEh bien, ce paladin est mort là-bas, et mes ennuis ont commencé comme ça.', 0),
(2201, 'frFR', 'Oui... Ce sont les Gemmes. Joli travail ! Malheureusement, ce n''est pas tout.$B$BNon, je ne cherche pas à enquiquiner le monde, stupide $C ! Il s''agit de forger de la magie, ici ! De la joaillerie magique estampillée Talvash del Kissel ! Vous avez besoin d''une forte Source d''énergie pour donner à ce Collier un peu de pep''s. Car ce collier ne dégage plus de pep''s...', 0),
(2202, 'frFR', 'Bravo, $N, vous avez prouvé votre valeur, une fois de plus ! L''étude de ces plantes sera passionnante !$B$BEt maintenant, comme promis, je vous offre un aperçu de l''une de mes préparations les plus revigorantes...$B$BSi vous êtes un alchimiste qualifié, nous pourrons peut-être continuer de travailler ensemble. De toute façon, merci pour votre aide !', 0),
(2204, 'frFR', 'Ben ça... Je suis ravi de vous voir en un seul morceau, cette Source d''énergie et vous ! Il va me falloir un moment pour fusionner le Collier et sa Source d''énergie par la magie, maintenant que les Gemmes ont retrouvé leur place... Et puis il sera à vous !$B$BPas d''impatience ! Vous frétillez de nervosité ! Bon... Où ai-je donc rangé ce sort...', 0),
(2283, 'frFR', 'Ouiiiii... Je sens le Collier d''ici... Voyons ce joyau...$B$BMais qu''est-ce que vous croyez ? Il manque les Gemmes ! Vous imaginiez qu''on ne s''en apercevrait pas ? Même Malton verrait qu''elles sont pas d''ssus !$B$BBon, OK, p''têt que vous les avez pas volées... Mais, de toute façon, ce collier n''vaut rien sans les Gemmes ! Le boulot est loin d''êt'' terminé !', 0),
(2338, 'frFR', 'Vous savez repérer une bonne affaire quand elle se présente ; je savais que je pouvais compter sur vous.$B$BPatientez un moment, le temps que je lance le sort qui traduira la langue humaine en un langage que vous comprendrez. Je suis un troll de parole ; renseignez-vous auprès de quiconque dans la Horde au sujet de Jarkal Mossmeld. Maintenant, commençons...', 0),
(2339, 'frFR', 'Bien joué, $C. Nous allons tirer les fruits de cet effort. J''en ai fini avec le Collier lui-même et je sais que je pourrai le dupliquer.$B$BJe vais rapidement analyser ces gemmes avec une incantation avant que vous les rapportiez à Orgrimmar avec le Collier. Ce ne sera pas long.', 0),
(2500, 'frFR', 'Ah ! Bien joué, $N ! Ça devrait me permettre de tenir un petit moment. Voici votre paye, comme promis.$B$BSi ça vous dit, j''ai également besoin de composants qu''on ne trouve que dans les profondeurs d''Uldaman. Ils ne seront pas facile à obtenir, mais je ferai en sorte que la récompense soit à la hauteur des efforts fournis.$B$BPeut-être autre chose que quelques pièces brillantes, hein ?', 0),
(2501, 'frFR', 'Je vous salue, et c''est le salut d''un Alchimiste à un autre Alchimiste. Voilà, prenez connaissance de cette recette. Vous connaîtrez peut-être grâce à elle le succès et les récompenses qu''elle m''a apportés au cours des ans.', 0),
(2521, 'frFR', 'Mes yeux me trompent-ils ? Impossible ! Où avez-vous ?... Comment ?...$B$BMaintenant, peut-être qu’une faille va pouvoir s’ouvrir afin que nous retournions chez nous.', 0),
(2523, 'frFR', 'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.', 0),
(2583, 'frFR', 'L''esprit du Sanglier vous illumine, $N ! Je me demande si vous vous sentez aussi invulnérable que ces bêtes ?', 0),
(2601, 'frFR', 'C''est merveilleux, $N ! Je vous offre un aperçu de mes travaux sur les basilics Rougepierre.$B$BJ''espère que la préparation va vous plaire. Il est toujours possible d''en faire davantage… en payant le prix.', 0),
(2602, 'frFR', 'Oui, oui, donnez-moi un moment et j''aurai davantage de produit à vous proposer, $N.$B$BPrenez cela... Et, $N, ne tentez pas d’ingurgiter ces mélanges expérimentaux les uns derrière les autres. Les résultats pourraient être désastreux.', 0),
(2604, 'frFR', 'J''arriverai peut-être un jour à isoler les enzymes actives de cette préparation, et ainsi renforcer son efficacité. Malheureusement, vous devez vous contenter de ce que je suis capable de produire aujourd''hui. Revenez me voir si vous voulez plus de Gomme de gésier.', 0),
(2623, 'frFR', 'C''est pire que ce que j''imaginais. On aurait pu épargner cette fin tragique à dix-neuf de mes hommes. Si seulement je n''avais pas réagi de façon aussi irrationnelle.$B$BVous devez les aider, $N ! Moi, je suis impuissant…', 0),
(2681, 'frFR', 'Vous avez réussi, $N ! Leurs pauvres âmes torturées peuvent enfin reposer en paix.$B$BNotre travail n''est pas encore fini, $N. Nous avons beaucoup à dire et encore plus à accomplir.', 0),
(2741, 'frFR', 'Vous placez l''œuf d''hippogryphe dans la machine. Des signaux sonores s''enchaînent, sur un fond de bruits mécaniques.$B$BEt le Calibre-œuf a pesé, mesuré et empaqueté votre œuf. Ça c''est du service rapide !', 0),
(2748, 'frFR', 'Excellent, $N. J''enverrai cet œuf à Darnassus où j''espère qu''il va bientôt éclore !$B$BAcceptez ceci en signe de ma gratitude.', 0),
(2749, 'frFR', 'Donc vous avez trouvé un œuf ordinaire, $N ? Donnez-le-moi s''il vous plaît... Nous allons espérer le meilleur pour lui.$B$BJe n''ai pas grand-chose, mais veuillez accepter cette récompense. Si vous retournez en Féralas, sachez que je serai toujours là pour recueillir les œufs que vous trouverez.', 0),
(2750, 'frFR', 'J''ai peur d''avoir de mauvaises nouvelles, $N. Cet œuf est à un stade trop avancé. Je peux le prendre pour nous en débarrasser proprement.$B$BMais ne vous découragez pas, nous ne pouvons pas tous les sauver. Si vous retournez en Féralas, retentez votre chance. Apportez un autre œuf pour le Super-Oeuf-O-Matic !', 0),
(2751, 'frFR', 'La lignée s’achève, mais la légende des Omosh va survivre !$B$BVous avez prouvé que vous avez l’âme d’un Forgeron, $N. La récompense du Forgeron, c''est la satisfaction de voir ses armes et ses armures couvertes du sang de l’ennemi !$B$BPuissent les plastrons que vous forgerez pour les générations futures ruisseler du sang de vos ennemis !', 0),
(2754, 'frFR', 'Étonnant ! Vous avez appris les secrets des Omosh, $N !', 0),
(2755, 'frFR', '< Orokk halète. >$B$BIl y a bien longtemps qu''Orokk n''a pas fait la Danse de joie des Omosh. Apprenez maintenant, $N !', 0),
(2756, 'frFR', 'Encore un sous-fifre complaisant du chef de guerre ! Quelle déception, $N...$B$BMoi qui rêvais d''une mort glorieuse au champ de bataille, je suis cantonné ici, par ordre de Thrall, à transmettre mon art aux enfants en bas âge ! Regardez et apprenez, gamin !', 0),
(2768, 'frFR', 'Vous l''avez trouvée ! Bien joué, $N ! Avez-vous eu besoin de vous battre avec Bly pour l''avoir ? J''espère que vous l''avez battu une bonne fois pour toutes, lui et sa bande !', 0),
(2782, 'frFR', 'Cette tablette… Plutôt inhabituelle… Où l''avez-vous trouvée, $N ?', 0),
(2854, 'frFR', 'Eh bien, $N ! Je suis heureux de vous avoir dans mon équipe. Vous avez pris une décision sage. Les porteurs d''armures en cuir se précipiteront quand ils sauront que vous maîtrisez l’art du cuir sauvage.$B$BAu travail, par où désirez-vous commencer ?', 0),
(2925, 'frFR', 'Oui ! J''ai besoin d''aide pour une mission dans Gnomeregan. Et vous m''avez l''air d''être la personne qu''il me faut, $C !', 0),
(2946, 'frFR', 'Comme vous touchez le socle, les disques miniatures se mettent à bourdonner et à rougeoyer dans votre sac à dos. Un picotement que vous connaissez parcourt vos mains tandis que l''image d''un deuxième Gardien des pierres se matérialise devant les Portes d''Uldum.$B$B"Salutations ! Je garde l''entrée, il manque aux disques que vous avez utilisés les Plaques d''Uldum. Veuillez incorporer ces plaques dans la structure des disques et répéter la séquence d''accès. Merci. "', 0),
(2963, 'frFR', 'Je suis content de voir que vous gardez du goût pour l''exploration, $N ! Vos talents peuvent nous servir à lever bien des mystères et des secrets !$B$BLes Disques de Norgannon étaient dépositaires d''importantes informations ; vous n''avez pu accéder qu''aux informations superficielles stockées là. Les Créateurs auraient laissé d''autres stocks d''informations partout dans Azeroth. Ce qui nous amène à Uldum...', 0),
(2966, 'frFR', 'Comme vous touchez le socle, les Disques miniatures se mettent à bourdonner et à rougeoyer dans votre sac à dos. Un picotement que vous connaissez parcourt vos mains tandis que l''image d''un deuxième Gardien des pierres se matérialise devant les Portes d''Uldum.$B$B"Salutations ! Je garde l''entrée, il manque aux disques que vous avez utilisés les Plaques d''Uldum. Veuillez incorporer ces Plaques dans la structure des disques et répéter la séquence d''accès. Merci. "', 0),
(2967, 'frFR', 'Il vous a manqué certains disques ? Ainsi les disques de Norgannon ne sont-ils qu''une partie du jeu complet, comme des clés sur un trousseau.$B$BSi nous pouvions trouver les Plaques d''Uldum, nous pourrions accéder au complexe d''Uldum lui-même. Je ne sais pas si je dois m''en réjouir ou en être terrifiée.$B$BNous devons faire tout ce qui est en notre pouvoir pour nous assurer que les secrets que la terre couve et qui pourraient tous nous détruire, restent... secrets.', 0),
(2968, 'frFR', 'Nous sommes tous d''accord : le mieux, pour l''instant, est d''attendre que nous puissions circonscrire suffisamment les zones où pourraient se trouver ces plaques. J''espère que vous serez celui qui retournera bientôt à Uldum pour en découvrir les secrets, $N.$B$BVoici déjà quelques honoraires pour couvrir les dépenses que vous avez faites en nous portant assistance, ainsi qu''un petit quelque chose en plus. Restez en contact avec nous. Uldum nous attend.', 0),
(2969, 'frFR', 'Elune soit louée, $N ! Vous êtes une bénédiction pour nous et les Fées fléchetteuses que vous avez sauvées. Jer''kai et moi, nous n''avons jamais été capables d''aider les dragons. Nous n''oublierons jamais votre intervention dans les affaires du Totem sinistre.$B$BParlez à Jer''kai... Je dois préparer notre vengeance. Ce n''est pas parce que les dragons féeriques sont libres qu''ils le resteront. Jer''kai et moi-même devons passer à l''offensive.', 0),
(2973, 'frFR', 'Merveilleux, $C ! Ils feront l''affaire. Il y en a assez pour faire une cape pour Korrin, peut-être plus ! Merci.$B$BJ''espère que le voyage n''a pas été trop dangereux. La région de Féralas n''est pas réputée pour être paisible. Mais vous avez réussi.$B$BMerci encore, $C.', 0),
(2984, 'frFR', 'Hum, Narm vous envoie, n''est-ce pas ?$B$BOn peut lui faire confiance, cela signifie que vous avez l''expérience requise pour le prochain sapta, le Sapta de feu.$B$BJe vois votre désir d''apprendre brûler dans vos pupilles. Vous avez de grands pouvoirs et l''envie d''en connaître de plus grands encore. Patience, $N. Rappelez-vous : force et pouvoir de destruction viendront facilement, le tout est de ne pas se précipiter.', 0),
(2991, 'frFR', 'Ah, le Médaillon de Nekrum. On dit qu''il a donné aux trolls une vie inhabituellement longue, mais à un prix élevé. Je souhaite découvrir un moyen de profiter de la puissance du Médaillon tout en évitant ses effets les plus déplaisants.$B$BVous m''avez rendu service, $N. Je vais remplir ma part du marché.', 0),
(3083, 'frFR', 'Jusqu''à nouvel ordre, vous serez sous ma tutelle. Je vais vous montrer les ficelles du métier, comme on dit. Dès que vous vous sentez apte, venez me retrouver pour poursuivre l''entraînement. Pour l''instant pratiquez ce que vous avez déjà appris, jusqu''à la maîtrise. La moindre petite compétence peut parfois sauver la vie, dans certaines situations.', 0),
(3085, 'frFR', 'Vous verrez que progressivement vous contrôlerez de mieux en mieux les esprits : vous les invoquerez pour des trucs de plus en plus forts... C''est là que le bon vieux Ken''jai intervient. Venez voir le vieux Ken''jai quand vous vous sentirez prêt. Si les esprits sont d''accord, alors p''têt'' qu''on vous apprendra des trucs plus puissants... Mais seulement si y sont d''accord.$B$BFilez, causez aux autres dans la Vallée. Revenez me voir plus tard.', 0),
(3086, 'frFR', 'Z''êtes parmi les êtres les plus puissants sur cette planète, $N... Pas de doute. Et tout le monde le sait... Faut que vous le sachiez !$B$BMais ça doit être lassant ! Car y a pas un orc, un elfe ou un nain qui vous fait peur... Mais gaffe aux trucs que vous pouvez pas voir. La magie est puissante, elle peut vous jouer des tours... Vous faire croire plus puissant que vous l''êtes. Un peu de patience et de réflexion ne sont pas du luxe.$B$BQuand vous le sentirez, revenez voir Mai''ah pour l''entraînement. Elle vous apprendra les trucs que vous devrez savoir, pas de problème.', 0),
(3088, 'frFR', 'Maintenant que vous savez ou je demeure, je peux vous le dire : la Main brisée m''a demandé de m''occuper de vous. Ils veulent que je vous entraîne et que je vous informe de tout ce dont ils pourraient avoir besoin. Même si les aider ne vous intéresse pas encore (ce qui serait idiot de votre part), je ferai ce que je peux pour vous entraîner... Pour une somme modique. Revenez quand vous voulez et nous verrons ce que vous êtes capable d''apprendre.', 0),
(3090, 'frFR', 'Maintenant, vous aussi avez rejoint nos rangs. Ne vous méprenez pas, $N. Que vous ayez accès à un pouvoir que nombreux vous envieront ne vous fera pas accepter plus facilement. Thrall nous accepte dans Orgrimmar car nous sommes encore de la famille. Il ne peut pas se détourner de nous, ou il deviendrait aussi pitoyable que les humains qui l''ont enchaîné. Bref... Prudence. Qu''importe votre puissance, si vous agissez stupidement votre mort est certaine.$B$BSi vous souhaitez apprendre de nouveaux sort, revenez me voir.', 0),
(3092, 'frFR', 'Et c''est mon rôle que de m''assurer de votre préparation en vous enseignant les bases de notre profession : comment dresser votre familier, vous servir de votre fusil et plein d''autres techniques qui vous seront nécessaires.$B$BLes chasseurs ont une part importante dans nos traditions et notre histoire, $N. N''oubliez jamais votre importance aux yeux de la tribu. Vous serez respecté et récompensé si vous servez bien notre peuple.', 0),
(3101, 'frFR', 'Par ailleurs, une ou deux choses à savoir. Pour beaucoup sur cette terre vous êtes un modèle : agissez en conséquence. Le Feu Sacré brille à travers vous et cela sera visible autant pour vos alliés que vos ennemis.$B$BAussi, à mesure que vous gagnerez en sagesse et en puissance, vous aurez besoin de vous former à de nouvelles techniques. C''est là que j''interviens. Quand vous sentirez que vous aurez gagné en expérience ici à Northshire, revenez me voir et je vous enseignerai ce que vous pourrez apprendre. Bonne chance... $C !', 0),
(3109, 'frFR', 'De toute façon, lorsque vous commencerez à explorer les Frigères, vous aurez sans doute besoin de formation à un moment ou à un autre. Revenez me voir à chaque fois que vous en ressentirez le besoin et je vous enseignerai ce que je sais. Une astuce, une manoeuvre... Vous savez, le genre de truc qui vous garde en vie et vous permet de gagner quelques piécettes.$B$BGardez l''oeil sur vos amis gnomes également... Ils sont bien esseulés depuis la destruction de Gnomeregan et ils auront besoin de notre aide pour se sentir chez eux ici.', 0),
(3110, 'frFR', 'Je suis celui qui pourra vous entraîner à mesure que vous connaîtrez un peu mieux la vallée des Frigères. Revenez me voir quand vous vous sentirez d''attaque et je verrai les nouveaux sorts que je pourrai vous apprendre pour faire déguerpir ces maudits troggs de notre vallée.$B$BLa Lumière est avec vous, et avec tout Ironforge, $N... On ne vous forcera pas à devenir quoi que soit de particulier.', 0),
(3115, 'frFR', 'Mais peu importe. Ce qui compte c''est que vous ayez vu votre propre Feu Sacré ! Vous connaissez la véritable origine du pouvoir. Vous comprenez qu''avoir nos propres alliés est bien plus... prudent. Des alliés particuliers. Des alliés qui, quelle que soit la mission, l''accompliront jusqu''au bout.$B$BEt c''est là que j''interviens, $N. Je peux vous apprendre les rudiments de ces pouvoirs spéciaux. Venez souvent me chercher et je vous apprendrai de nouveaux sorts.', 0),
(3116, 'frFR', 'Bientôt vous verrez d''autres gens, de races différentes, dans les branches de notre maison. Que cela ne vous chagrine pas : ils sont les bienvenus. Ils nous aideront quand ils pourront. Ils ne seront pas tous aussi altruistes, mais ils méritent tout de même notre confiance.$B$BMais cela n''a pas vraiment d''importance. Maintenant parlons de vous et de la façon dont vous aiderez notre peuple. C''est pour ça que je suis ici. Je vous apprendrai la voie du $C à mesure que vous gagnerez en force. Revenez me voir quand vous le souhaiterez et je ferai ce que je peux pour vous aider.', 0),
(3126, 'frFR', 'Merci, $N. Notre collection de miniatures est presque complète.', 0),
(3127, 'frFR', 'Imaginez les possibilités offertes par ce que nous possédons désormais, $N. Grâce à ce que vous avez collecté, je suis désormais capable de placer la version miniature de ces créatures dans tout ce que je désire.', 0),
(3182, 'frFR', 'Qu''est-ce que c''est ?$B$BOh, je ne peux pas le croire ! Vous savez ce que vous avez là, $N ? C''est la Corne de Margol l''Enragée ! Margol ! Le fléau de tout archéologue qui ait jamais pénétré dans la Gorge des Vents brûlants.$B$BPuis-je la garder ?', 0),
(3363, 'frFR', 'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.', 0),
(3374, 'frFR', 'Vous avez fait votre choix. Jusqu''à présent, vous avez fait des choix qui m''ont semblé justes. Dorénavant, vos actes et vos faits détermineront si cela doit rester le cas.', 0),
(3375, 'frFR', 'Le puissant aventurier arrive enfin avec la cargaison. Hourra !! Oh, à propos, j''ai menti… j''avais une autre fiole. Prenez-la, allez.$B$BEt alors, vous vous attendiez à quoi ?! "Oh, mais je vous en prie, prenez donc ! Je ne suis qu''un rigolo qui n''a rien d''autre à faire que de distribuer des outils magiques de communication à tous les aventuriers qui passent dans le secteur !" Dormez tranquille, quand même, ce que vous m''avez apporté suffira à l''élaboration d''une autre fiole quand vous aurez égaré celle-là aussi.$B$BPar pitié, ne me donnez pas raison, et ne perdez pas celle que je viens de vous donner, d''accord ?', 0),
(3379, 'frFR', 'Excellent travail, $N.$B$BJe crois ne pas me tromper en disant que ceci est une pièce de tisse-ombre que vous n''avez encore jamais vue.', 0),
(3385, 'frFR', 'Vous avez porté un coup décisif au Sous-marché. Leurs chefs y réfléchiront à deux fois avant d''envoyer de nouveaux hommes dans le gouffre.$B$BOh, et je n''ai également rien trouvé qui m''intéresse dans la sacoche du marchand. Vous pouvez garder tout ce que vous y trouverez.', 0),
(3402, 'frFR', 'Kovic est mort ??! C''est un grand jour, $N ! Durant des années, cette crapule a organisé des commerces louches et véreux, à vendre moins cher que les honnêtes commerçants.$B$BVous méritez une belle récompense pour cette réussite ! Et vous l''aurez !', 0),
(3444, 'frFR', 'Oui... il s''agit bien de cette pierre.$B$BTout me revient à présent, $N...', 0),
(3450, 'frFR', 'Que puis-je faire pour vous, $N ? Je suis plutôt occupé en ce moment. Je prépare mon appareil pour un long voyage. Je passais juste pour voir les conducteurs de chars, j''ai besoin de quelques crinières de Wendigos pour embellir mon cockpit et ils en ont toujours en trop d''ordinaire.$B$BJe peux vous accorder une minute si vous faites vite... l''un des gars vient de décoller pour le Dépôt de Steelgrill pour voir s''il n''y a pas de crinières en trop que je pourrais prendre.', 0),
(3506, 'frFR', 'Ah ! Incroyable !$B$BVous avez réussi ! Belgrom sera heureux ! L''esprit de douzaines de nos guerriers va enfin retrouver la paix. Merci, $N.', 0),
(3510, 'frFR', 'Enfin une personne digne de la sagesse d''Arkkoroc !', 0),
(3511, 'frFR', 'Le durcisseur ajoutera ce qui nous manquait pour créer ces armes. Il n''y a plus qu''une étape dans leur création.', 0),
(3512, 'frFR', 'Itharius a été sage de vous envoyer à moi. Même s''il n''est pas mort au sens où vous l''entendez, Eranikus nous parlera bientôt lui-même. Pour le moment cependant, je ne peux pas directement vous aider... pas encore.$B$BJe me mets à votre disposition mais d''abord j''ai besoin de l''aide de quelqu''un qui (à la différence de moi) n''est pas limité par la vieillesse. Mon instrument d''augure le plus puissant m''a été pris et à moins de le récupérer, nous n''arriverons pas à aider Eranikus.', 0),
(3526, 'frFR', 'Bien $N, vous avez été avisé de choisir mon enseignement ! N''importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d''Ingénierie des gobelins.$B$BOuvrez vos oreilles, $N, et vous pourrez apprendre beaucoup.', 0),
(3528, 'frFR', 'L''essence d''Hakkar a été trouvée ! Et même, l''œuf revient maintenant à la vie ! Les mythes d''Hakkar pourraient-ils être vrais ?$B$BCe n''est pas possible, ou alors, j''ai peur de ce que pourrait faire Hakkar s''il naissait de nouveau. Je vais enfermer l''œuf dans ce coffre-fort pour qu''il ne tombe pas dans de mauvaises mains.$B$BVotre travail pour moi est terminé, $N. Vous entrez dans la légende et vos actions changeront peut-être un jour la face de notre monde.', 0),
(3564, 'frFR', 'Parfait... Attendez un instant.$B$BHa ha ! Que lui avez-vous dit quand vous avez livré la tablette, $N ? Il nous a plus que surpayés ! ce n''est pas que je me plaigne. Lui avez-vous dit que l''accord avait changé ? Ou avait-il encore bu ?$B$BAucune importance... Prenez une part supplémentaire vous aussi.', 0),
(3602, 'frFR', 'Votre tâche à Azshara est terminée. Je dois maintenant forger ce qui va vous être nécessaire pour poursuivre vos aventures.', 0),
(3621, 'frFR', 'Bon sang ! Je ne peux qu''imaginer ce que vous avez dû subir pour obtenir cela. Peu nombreux sont ceux qui vont à Azshara et reviennent en vie ; sans parler des affrontements avec ces demi-dieux et ces géants !', 0),
(3629, 'frFR', 'Bien $N, vous avez été avisée de choisir mon enseignement ! N''importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d''Ingénierie des gobelins.$B$BOuvrez vos oreilles, $N, et vous pourrez apprendre beaucoup.', 0),
(3633, 'frFR', 'Bien $N, vous avez été avisé de choisir mon enseignement ! N''importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d''Ingénierie des gobelins.$B$BOuvrez vos oreilles, $N, et vous pourrez apprendre beaucoup.', 0),
(3635, 'frFR', 'Vous venez pour apprendre l''ingénierie gnome, alors ? Bien, vous vous adressez au bon gnome. Même si la faction dirigeante de Gnomeregan utilise la politique pour frapper d''ostracisme ceux qu''ils perçoivent comme une menace intellectuelle, ils savent qu''ils ne peuvent pas contrôler la connaissance.$B$BIls savent comme moi que si je quitte Gnomeregan, ils perdront un de leurs plus grands ingénieurs gnomes vivants aujourd''hui. Si vous vous montrez capable, je vous apprendrai ce que je sais.', 0),
(3637, 'frFR', 'Vous venez pour apprendre l''ingénierie gnome, alors ? Bien, vous vous adressez au bon gnome. Même si la faction dirigeante de Gnomeregan utilise la politique pour frapper d''ostracisme ceux qu''ils perçoivent comme une menace intellectuelle, ils savent qu''ils ne peuvent pas contrôler la connaissance.$B$BIls savent comme moi que si je quitte Gnomeregan, ils perdront un de leurs plus grands ingénieurs gnomes vivants aujourd''hui. Si vous vous montrez capable, je vous apprendrai ce que je sais.', 0),
(3642, 'frFR', 'Bienvenue à bord, $N ! Vous aurez bientôt accès aux schémas de l''ingénierie la plus avancée de tout Azeroth.$B$BPuisque vous avez décidé de poursuivre dans cette voie, il est temps d''examiner votre technique de travail d''Ingénierie Gnome. Ensuite, nous vous aiderons à maximiser vos talents !', 0),
(3644, 'frFR', 'Puisque vous pratiquez l''Ingénierie des gobelins depuis un certain temps, je peux renouveler votre Carte de membre expirée contre un paiement de deux pièces d''or. Une fois ces frais de renouvellement acquittés, on vous remettra une nouvelle Carte de membre. Cela vous permettra d''obtenir des schémas d''Ingénierie des gobelins chez les Entraîneurs concernés.$B$BLe délai de validité de cette carte sera de deux semaines d''activité, à l''issue desquelles les frais d''adhésion devront à nouveau être payés. Si vous voulez accéder aux schémas, vous devrez apporter cette somme, mais pas les arriérés.', 0),
(3645, 'frFR', 'Puisque vous pratiquez l''Ingénierie des gnomes depuis un certain temps, je peux renouveler votre Carte de membre expirée contre un paiement de deux pièces d''or. Une fois ces frais de renouvellement acquittés, on vous remettra une nouvelle Carte de membre. Cela vous permettra d''obtenir des schémas d''Ingénierie des gnomes chez les Entraîneurs concernés.$B$BLa validité de cette carte est de deux semaines, à l''issue desquelles vos frais d''adhésion devront à nouveau être payés. Si vous voulez accéder aux schémas, vous devrez apporter cette somme, mais pas les arriérés.', 0),
(3646, 'frFR', 'Puisque vous pratiquez l''Ingénierie des gobelins depuis un certain temps, je peux renouveler votre Carte de membre expirée contre un paiement de deux pièces d''or. Une fois ces frais de renouvellement acquittés, on vous remettra une nouvelle Carte de membre. Cela vous permettra d''obtenir des schémas d''Ingénierie des gobelins chez les Entraîneurs concernés.$B$BLe délai de validité de cette carte sera de deux semaines d''activité, à l''issue desquelles les frais d''adhésion devront à nouveau être payés. Si vous voulez accéder aux schémas, vous devrez apporter cette somme, mais pas les arriérés.', 0),
(3762, 'frFR', 'Salutations, $C. Je suis heureux de voir que vous êtes intéressé pour nous prêter main-forte. Il y a beaucoup à faire, et ce ne serait pas vous rendre service que de vous dire que ce travail ne comporte aucun danger. J''espère que cela ne va pas vous effrayer... Mais en vous regardant, il me semble comprendre que vous avez déjà eu à faire au danger.', 0),
(3790, 'frFR', 'Bien, $C… Puisque vous avez été informé que je dirigeais en personne ces recherches, vous êtes évidemment venu aussi vite que possible.$B$BMaintenant que vous êtes là, écoutez attentivement. J''ai horreur de me répéter.', 0),
(3792, 'frFR', 'Merci, $N. Je vais juste la mettre de côté pour l''instant. Bien que ce ne soit pas moi le responsable des ressources de Staghelm, je peux vous donner un petit quelque chose pour le dérangement. De toute façon, qui sait ce qu''il va arriver si Staghelm continue à s’approvisionner en Fibre d''aurore. Il y a quelque chose de louche derrière tout ça, croyez-moi.$B$BRappelez-vous que j''accepte toujours de la Fibre d''aurore. Je la prends par brassée de cinq.', 0),
(3906, 'frFR', 'Cela ne peut être… cela ne doit pas être ! La mort de Pyron a simplement levé un voile. Il se trouve à présent dans les Profondeurs de Blackrock une source de corruption mille fois plus insidieuse.', 0),
(3907, 'frFR', '<Thunderheart s''empare de la Tablette de Kurniya. >$B$BRagnaros... là...$B$BLes anciens avaient raison de craindre la corruption émanant du mont Blackrock. Un général des Dieux très anciens ! DANS NOTRE MONDE ! Nous devons réexaminer notre position ici à Kargath. Nous devons décider si nous restons pour nous battre ou si nous fuyons de crainte d’une nouvelle Fracture.$B$BSoyez particulièrement prudent si vous explorez à nouveau le mont Blackrock, $N. Un mal plus puissant que tout ce qui réside en ce monde demeure en ses profondeurs ardentes.', 0),
(3909, 'frFR', 'Je vais avoir besoin d''une fiole pour m''assurer qu''il s''agit bien de l''élixir… Oui… C''est bien cela.', 0),
(3922, 'frFR', 'Parfait, vous les avez ! À présent je peux commencer à travailler…', 0),
(4022, 'frFR', '<Cyrus examine l''écaille.>$B$BVous avez prouvé que vous n''étiez pas complètement inutile, mortel.', 0),
(4024, 'frFR', '<Cyrus vous arrache l''Essence ardente des mains. >$B$BOUI !$B$BPrenez votre prix et partez. Sortez de ma vue immédiatement.', 0),
(4041, 'frFR', 'Alors, vous en avez mis une au vieux Miblon, hein ?', 0),
(4063, 'frFR', 'Qu''est-ce que c''est ?! Cette tête n''est pas faite de chair. C''est un genre de création Sombrefer. Une ombre d''Argelmach. UNE AUTRE machine ! Je suspecte que votre exploit soit de courte durée, car un autre Argelmach va bientôt se lever et prendre ''sa'' place.', 0),
(4103, 'frFR', 'Très bien donc, voici vos doses de Baume cénarien. Fouillez Gangrebois pour trouver ces plantes corrompues, $N ! Où qu''elles soient, utilisez le Baume que je vous ai donné pour les purifier.', 0),
(4104, 'frFR', 'Très bien. Voici des doses de baume cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux confectionner de baume.', 0),
(4105, 'frFR', 'Excellent travail, $N. Chacune d''elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, $N !', 0),
(4106, 'frFR', 'C''est exactement ce dont j''ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et servez-vous-en pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, $N !', 0),
(4107, 'frFR', 'Voilà quelques doses de Baume végétal cénarien ; il ne manque plus qu''une Essence du néant inférieure, $N. Cette essence est de loin l''objet le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !', 0),
(4108, 'frFR', 'Très bien donc, voici vos doses de Baume cénarien. Fouillez Gangrebois pour trouver ces plantes corrompues, $N ! Où qu''elles soient, utilisez le Baume que je vous ai donné pour les purifier.', 0),
(4109, 'frFR', 'Très bien. Voici quelques doses de Baume cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux confectionner de baume.', 0),
(4110, 'frFR', 'Excellent travail, $N. Chacune d''elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, $N !', 0),
(4111, 'frFR', 'C''est exactement ce dont j''ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et servez-vous-en pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, $N !', 0),
(4112, 'frFR', 'Voilà quelques doses de Baume végétal cénarien ; il ne manque plus qu''une Essence du néant inférieure, $N. Cette essence est de loin l''objet le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !', 0),
(4113, 'frFR', 'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.', 0),
(4114, 'frFR', 'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.', 0),
(4115, 'frFR', 'Vous appliquez deux doses de baume cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s''épanouir en une plante vibrante de santé.', 0),
(4116, 'frFR', 'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.', 0),
(4118, 'frFR', 'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.', 0),
(4121, 'frFR', 'Vos actes héroïques ne seront pas oubliés, $N. Vous avez gagné ce tribut. Le Chef de guerre va vous parler à présent de la dernière mission.', 0),
(4122, 'frFR', 'Ne pouvez-vous pas comprendre le pouvoir que l''on gagne à rejoindre la légion de Blackrock ?', 0),
(4126, 'frFR', 'Vous l''avez retrouvée ! Beau travail ! Et j''espère que vous avez mis une bonne trempe à ces nains Sombrefer et à ce Hurley Blackbreath !$B$BLes Thunderbrew sont à votre service, $N. Vous êtes le héros des héros.', 0),
(4133, 'frFR', 'Je vous remercie d''être venu, $N. L''austérité de cet endroit dégage un certain charme, mais les aménagements de l''Apothicarium lui font toutefois défaut.$B$BMais assez de politesses. Parlons devoir, d''accord ?', 0),
(4134, 'frFR', 'Très bien. Je vais envoyer cette recette chez l''Apothicaire afin qu''elle y soit étudiée. Et nous percerons ses mystères un jour. Il se peut que dans le futur, les nains de l''Alliance voient les vertus de cette boisson se retourner contre eux !$B$BJe trouve cela terriblement amusant. Peut-être que la mort influence le sens de l''humour de chacun... Qu''en pensez-vous ?', 0),
(4144, 'frFR', 'Et voilà, $N ! Cela va occuper Larion !', 0),
(4148, 'frFR', 'Il semble que cela va fonctionner, $N. À présent, rappelez-vous de ceci : si vous voyez la moindre de ces pestes aux alentours, n''hésitez pas à utiliser cette baguette !', 0),
(4181, 'frFR', 'Bien $N, vous avez été avisé de choisir mon enseignement ! N''importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d''ingénierie des gobelins.$B$BOuvrez vos oreilles, $N, et vous pourrez apprendre beaucoup.', 0),
(4201, 'frFR', 'Oh, vous avez réussi ! À présent je peux préparer ma potion et m''en servir sur Rocknot. Il va enfin succomber à mes charmes !$B$BMerci, $N. Vous êtes un champion de l''amour !', 0),
(4221, 'frFR', 'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s''épanouir en une plante vibrante de santé.', 0),
(4294, 'frFR', 'Vraiment ahurissant, $N. Ce cratère d''Un''Goro renferme bien plus de secrets que je ne l''espérais. Je me demande ce que nous allons découvrir en nous enfonçant plus avant.$B$BC''est vraiment incroyable... Regardez comme ces échantillons sont purs. Hm, Je me demande ce que ça signifie. Ils semblent être de nature élémentaire, mais... ce n''est pas tout. Ils me rappellent... les Dieux très anciens. Nous avons trouvé des preuves de leur existence un peu partout dans Azeroth, et je me demande si ces créatures n''ont pas quelque chose à voir avec eux.$B$BNous verrons ça plus tard.', 0),
(4341, 'frFR', 'S''il vous plaît, laissez-moi expliquer.', 0),
(4342, 'frFR', 'Comme vous pouvez le voir, je ne pouvais rien faire.', 0),
(4361, 'frFR', '<Le roi Magni abat son poing avec colère. >', 0),
(4381, 'frFR', 'Tandis que vous arrangez les cristaux sur la table, vous alignez précautionneusement les couleurs. Lorsque vous placez le dernier, une explosion de lumière intense mêle les cristaux entre eux.$B$BLe résultat vous appartient.', 0),
(4401, 'frFR', 'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.', 0),
(4402, 'frFR', 'Merveilleux, $N ! Comme promis, voici votre surprise aux pommes de cactus plus un petit quelque chose.', 0),
(4466, 'frFR', 'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s''épanouir en une plante vibrante de santé.', 0),
(4467, 'frFR', 'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s''épanouir en une plante vibrante de santé.', 0),
(4493, 'frFR', 'Oui, j''ai conclu que c''est Gracina qui vous envoie. Votre expérience du combat contre ces créatures est inestimable ; personne à ma connaissance n''a jamais affronté cette espèce auparavant. Puisque Gracina pense que le cratère d''Un''Goro est leur berceau... Ça doit être le cas. Un''Goro est une jungle mystérieuse et dangereuse qui se trouve à l''ouest. Peut-être sommes-nous en train de faire un pas supplémentaire vers la résolution du mystère des silithides.', 0),
(4494, 'frFR', 'Oui, j''ai bien compris que c''est Zilzibin qui vous envoie. Votre expérience du combat contre ces créatures est inestimable ; personne à ma connaissance n''a jamais affronté cette espèce auparavant. Puisque Zil pense que le cratère d''Un''Goro est leur berceau... ça doit être le cas. Un''Goro est une jungle mystérieuse et dangereuse qui se trouve à l''ouest. Peut-être sommes-nous en train de faire un pas supplémentaire vers la résolution du mystère des silithides.', 0),
(4507, 'frFR', 'Fantastique, $N ! Nous avons remporté une victoire aujourd''hui. Cela nous prendra un moment pour comprendre vraiment ce que nous avons ici ; nous l''utiliserons à bon escient, ne vous inquiétez pas pour ça.$B$BComme pour les silithides, je doute que nous ayons exterminé toute trace de leur présence. Je dois bien admettre que c''était un vœu pieux.', 0),
(4508, 'frFR', 'Bien que je sois réellement satisfaite, je ne suis pas certaine du bien que ça nous fera. L''Alliance ignore toutes les menaces qui ne sont pas relatives à la Horde et nos chefs eux-mêmes, à Darnassus, ne peuvent s''accorder sur la nature de cette menace. Les imbéciles comme Fandral Forteramure pensent que les silithides ne sont pas la menace surgie du passé que je pense. Son ignorance n''a d''égale que son arrogance.$B$BVous avez été confronté à la menace, $N. Nous devons rester mobilisés pour vaincre les silithides !', 0),
(4511, 'frFR', 'Ce reçu bancaire m''autorise à retirer un objet du compte que Zilzibin Drumlore possède chez nous et à vous le remettre. Des félicitations sont de rigueur !', 0),
(4512, 'frFR', 'Des résultats impressionnants, $N ! Vous vous êtes suffisamment approché pour récupérer un échantillon de ces choses corrompues sans y laisser des plumes ! Merci. Oh, ces échantillons conviendront parfaitement. Je suis impatient de commencer les tests dessus.$B$BSi j''ai raison, je pourrais bien être l''un des plus grands scientifiques de la Ligue des explorateurs !$B$BCela prouvera aux nains que ce n''était pas une erreur de nous accueillir dans Ironforge après les incidents de Gnomeregan.', 0),
(4561, 'frFR', 'Vous ramassez la boîte de pétri qui contient l''échantillon de Limon. Le seul moyen de s''assurer de la pureté de l''échantillon est de l''ouvrir et de l''examiner vous-même. Idéalement, vous trouverez un échantillon qui remplit les critères énoncés par le Chimiste Fuely.', 0),
(4642, 'frFR', 'Oh, parfait, $N. C''est merveilleux.$B$BQuelle histoire. Qui aurait cru que ces deux-là interagiraient de cette manière... Il faut que je passe plus de temps à observer les retombées environnementales qui ont provoqué les mutations de ces créatures.$B$BJe vais continuer mes recherches. Peut-être en reparlerons-nous bientôt. Jusque là je vous souhaite bonne chance.', 0),
(4661, 'frFR', 'Vous ramassez la boîte de pétri qui contient l''échantillon de Limon. Le seul moyen de s''assurer de la pureté de l''échantillon est de l''ouvrir et de l''examiner vous-même. Idéalement, vous trouverez un échantillon qui remplit les critères énoncés par le Chimiste Fuely.', 0),
(4681, 'frFR', 'Vous avez été d''une aide inestimable aujourd''hui ; désormais nous avons une chance non négligeable d''élucider le mystère de ces créatures qui ont choisi de venir s''échouer sur la côte de Sombrivage. L''idée qu''elles essaient peut-être de fuir les rivages de Teldrassil est inquiétante. Si vous en rencontrez d''autres dans vos voyages, informez-m''en. Nos recherches n''en sont qu''au début.$B$BVeuillez accepter ceci, de la part du temple de la Lune, pour vous remercier de vos efforts. Merci, $N !', 0),
(4726, 'frFR', 'Ça a fonctionné ! Vous avez l''essence ! Très bien, $N ! Très bien !$B$BCette essence est inestimable pour mes recherches. J''espère qu''un jour j''apprendrai à capturer des dragonnets vivants ou peut-être leurs œufs. Si je trouve un moyen d''y arriver, je serais enviée par toutes les personnes qui étudient les dragons !$B$BMon patron sera heureux aussi, et comme je l''ai dit plus tôt, c''est quelqu''un qu''il faut ménager...', 0),
(4730, 'frFR', 'Les ossements que vous avez découverts proviennent des mammifères marins qui peuplent les eaux qui entourent la base de Teldrassil. Ils ne sont pas réputés pour venir s''échouer sur les plages comme nous avons pu le constater avec les batteurs. Je me demande pourquoi ces créatures agissent de la sorte ? Peut-être que l''étude de ces restes nous apportera des éléments de réponse.$B$BEncore une fois, merci pour votre aide. Veuillez accepter cette modeste récompense de la part du Temple de la lune.', 0),
(4734, 'frFR', 'Ça a marché ? Splendide ! Je savais que ça serait le cas !$B$BPendant que vous étiez parti j''ai travaillé sur une nouvelle version de l''Oeufilloscope. Celui-ci a une portée plus longue.$B$BVoilà, vous pouvez vous en procurer un au cas où vous retourneriez au pic Blackrock.', 0),
(4735, 'frFR', 'Wow, vous les avez ! Le Module collectronique a fonctionné ! Je suis un génie !$B$BMerci, $N. Mon client sera très content de récupérer ces oeufs...', 0),
(4762, 'frFR', 'Il n''est pas surprenant que cette eau soit corrompue, regardez comme elle est croupie ! Il semble qu''il soit plus que temps d''agir, n''est-ce pas, $N ?$B$BÀ l''est, il y a Gangrebois ; c''est là-bas qu''à l''époque j''ai vu ce qui doit être à l''origine de cette corruption. Je pense que cet échantillon le confirmera. Nous devrions pouvoir préparer un remède, mais il nous faudra de l''aide. Quand le moment sera venu, $N, j''espère que vous répondrez à notre appel.', 0),
(4764, 'frFR', 'Vous l''avez trouvé ! Les rumeurs étaient donc vraies !$B$BMerci, $N. Mon client, le comte Remington Ridgewell, sera content de voir cette pièce rejoindre sa collection.', 0),
(4788, 'frFR', 'Incroyable ! Vous les avez trouvées ! Vous êtes un vrai héros, $N !$B$BD''ailleurs, c''est une bonne chose, car d''après ce que j''ai déchiffré des tablettes que vous m''aviez apportées… Il nous faudra un vrai héros pour arrêter ce qui arrive...', 0),
(4801, 'frFR', 'Mau''ari peut utiliser ce juju pour $N... Utiliser la Cache de Mau''ari pour la lancer sur vous ou l''un de vos alliés.', 0),
(4804, 'frFR', 'Mau''ari peut utiliser ce juju pour $N... Utiliser la Cache de Mau''ari pour la lancer sur vous ou l''un de vos alliés.', 0),
(4806, 'frFR', 'Mau''ari peut utiliser ce juju pour $N... Utiliser la Cache de Mau''ari pour la lancer sur vous ou l''un de vos alliés.', 0),
(4809, 'frFR', 'Ce sont de beaux spécimens. Ils sont bien glacés ! Laissez-moi mettre des gants et les ranger avec les autres choses dont Tinkee a besoin...', 0),
(4811, 'frFR', 'Alors le cristal existe, $N ? Fascinant… Quoi qu''il en soit, vous avez parfaitement exécuté votre tâche ; bon travail !$B$BQu''est-ce que ce cristal exactement ? Ce n''est qu''une simple question dans un océan d''interrogations. Une autre question qui vient à l''esprit, est pourquoi les séléniens sont-ils attirés par cet objet ? Le cristal est-il bon de nature, ou renferme-t-il un secret plus sombre ?$B$BJ''ai beaucoup d''autres questions, mais il va nous falloir examiner ce cristal de près pour trouver des réponses.', 0),
(4867, 'frFR', 'Aha ! Je sens déjà mes pouvoirs me revenir. Et mon esprit n''est plus brisé par la malédiction d''Urok.$B$BMerci, $N ! Je suis fier, mais je dois reconnaître votre aide précieuse.$B$BEt je vous souhaite chance et prospérité pour votre voyage par le pic Blackrock. Vous êtes fou de penser pouvoir en atteindre le sommet, mais je rends grâce à votre courage.', 0),
(4882, 'frFR', 'Une découverte importante ?', 0),
(4982, 'frFR', 'Vous avez réussi ! Une fois que Lexlort aura ces plans, Il oubliera toutes les vilaines choses qu''il voulait m''infliger.$B$B$N, vous êtes mon héros !', 0),
(5041, 'frFR', 'Ha ha ! Merci, $N ! Cela nous est d''une grande aide. Vous êtes une bénédiction pour la Croisée et la Horde. Si je puis faire quelque chose pour vous, je vous en prie, dites-le-moi.', 0),
(5042, 'frFR', 'Si seulement Mutiledent était libre pour vous voir décimer ceux qui l''ont trahi ! <grogne>$B$BMerci d''avoir détruit plus de Dos-hirsute en ramassant ces joyaux. S''il vous plaît, continuez ainsi, et je continuerai à vous aider. <grogne>', 0),
(5047, 'frFR', 'Vivant ? Et la tenue a fonctionné ? Et qu''avons-nous là ?', 0),
(5057, 'frFR', 'Nous apprenons de nos expériences, $N. Vous n''avez pu que grandir en force et en sagesse grâce aux vôtres. Vous avez bien mûri depuis notre dernière entrevue.$B$BPrenez ceci en souvenir des tâches difficiles que vous avez accomplies en tant que $C $R, et sachez que vous aurez toujours droit à mon respect et à mon admiration.', 0),
(5059, 'frFR', 'En utilisant la clé trouvée sur le corps de feue Mme Dalson, vous ouvrez la porte des toilettes. Une goule assoiffée de sang en jaillit, enfermée ici on ne sait depuis combien de temps.$B$BLe hurlement à glacer le sang lancé par la goule ne laisse aucun doute, l''ancien fermier Dalson est au-delà de tout espoir de guérison.', 0),
(5060, 'frFR', 'La clé prise sur le cadavre de la goule du fermier Dalson glisse parfaitement dans la serrure. Les portes de la commode s''ouvrent, révélant plusieurs objets intacts et de grande valeur.', 0),
(5081, 'frFR', 'Excellent travail, $N ! Au minimum, vous nous avez gagné du temps supplémentaire - un temps très, très précieux.', 0),
(5090, 'frFR', 'Bienvenue dans les Maleterres, héros. C''est l''une des frontières les plus dangereuses d''Azeroth, particulièrement avec la menace rampante du Fléau, au nord et nord-est. Quel bonheur de voir que l''appel du devoir et le service du bien ne sont pas tombés dans les oreilles d''un sourd en ce qui vous concerne !$B$BSi vous voulez mettre la main à la pâte, alors il y a aux confins des Maleterres de quoi faire pour de nombreux héros volontaires et capables.', 0),
(5091, 'frFR', 'Bienvenue dans les Maleterres, héros. C''est l''une des frontières les plus dangereuses d''Azeroth, particulièrement avec la menace rampante du Fléau, au nord et nord-est. Quel bonheur de voir que l''appel du devoir et le service du bien ne sont pas tombés dans les oreilles d''un sourd en ce qui vous concerne !$B$BSi vous voulez mettre la main à la pâte, alors il y a aux confins des Maleterres de quoi faire pour de nombreux héros volontaires et capables.', 0),
(5092, 'frFR', 'Mission accomplie, $N ! Bien joué, bien joué.$B$BPermettez-moi de récompenser votre travail par quelques pièces des coffres de Hurlevent. Je vous recommande de le dépenser en prévision de votre prochaine mission… qui vous conduira aux ruines d''Andorhal elles-mêmes.$B$BSoyez prêt ! Soyez vigilant !', 0),
(5094, 'frFR', 'Bienvenue aux Maleterres, héros. C''est la plus dangereuse des frontières d''Azeroth, avec l''ombre menaçante du Fléau à l''est, et plus à l''est encore. Je suis heureux de constater que l''appel au sens du devoir de la Horde n''a pas trouvé sourde oreille en vous !$B$BSi on est prêt à se salir les mains, il y a de quoi faire pour les héros ici, à la limite des Maleterres.', 0),
(5095, 'frFR', 'Bienvenue aux Maleterres, héros. C''est la plus dangereuse des frontières d''Azeroth, avec l''ombre menaçante du Fléau à l''est, et plus à l''est encore. Je suis heureux de constater que l''appel au sens du devoir de la Horde n''a pas trouvé sourde oreille en vous !$B$BSi vous êtes prêt à vous salir les mains, il y a de quoi faire pour les héros ici, à la limite des Maleterres.', 0),
(5097, 'frFR', 'Mes prêtres m''informent que nos traqueurs de balises détectent des signaux très forts sur les quatre tours ! J''ose à peine le dire, mais je crois que vous avez effectué une nouvelle mission avec un succès complet et total ! Bien joué à nouveau, $N !$B$BUne fois les tours marquées, nos préparatifs pour l''attaque sont désormais en place. Le temps est venu d''engager le combat contre le Fléau !', 0),
(5098, 'frFR', 'Mes démonistes m''informent que nos traqueurs de balises détectent des signaux très forts sur les quatre tours ! Vous avez exécuté mes ordres avec l''habileté et la précision d''un vétéran aguerri. Vos services sous la bannière de la Horde sont remarqués une fois encore, $N !$B$BUne fois les tours marquées, nos préparatifs pour l''attaque sont désormais en place. Le temps est venu d''engager le combat contre le Fléau !', 0),
(5126, 'frFR', '<Lorax rit.>', 0),
(5150, 'frFR', 'Les pousses posées devant elle, Dadanga semble satisfaite.$B$BElle pousse un petit paquet enveloppé de brun vers vous, en échange du petit cadeau !', 0),
(5160, 'frFR', 'Les Aspects insistent pour que nous n''intervenions pas dans les affaires des mortels. Dans ce monde pourtant cela n''est pas toujours le cas, spécialement lorsque l''un des nôtres méprise de telles règles.', 0),
(5162, 'frFR', 'Je suis Jeziba, que l''on connaît surtout sous le nom de Sculpteur. Ce que je sculpte cependant, ce ne sont pas des statues, mais des héros.', 0),
(5164, 'frFR', 'Des centaines et des centaines de pages de gribouillis ésotériques composent l''essentiel de ce livre.', 0),
(5166, 'frFR', 'Ne comprenez-vous toujours pas ? Le voyage était la destination. Pouvez-vous ignorer les cicatrices des combats ? La peine que vous avez eue ?$B$BDu fait d''avoir survécu à cette épreuve, vous en êtes sorti grandi. Cette cuirasse n''est qu''un pâle reflet de vos propres dons.', 0),
(5167, 'frFR', 'Ils sentiront l''odeur de leur parent lorsque vous entrerez dans leurs couloirs, $N. Écrasez-les avec leur propre peur !', 0),
(5168, 'frFR', 'Vous avez le grimoire et le bouclier !$B$BLeur histoire est intimement liée à celle de Comté-de-Darrow ; et je sais que, d''une façon ou d''une autre, le destin les rassemblera.', 0),
(5220, 'frFR', 'Ah, il y a matière à analyse ici. Bien joué, $N !$B$BA nous de jouer maintenant. Nous devrons dresser la liste des composants qui, combinés au contenu du chaudron, en inverseront les effets.$B$BLe seul moyen sera de mélanger ces composants dans le chaudron même. L''alchimiste Arbington en saura plus, parlez-lui au plus tôt.', 0),
(5223, 'frFR', 'Une nouvelle mission réussie, $N ! Cela fait trois chaudrons que nous pourrons retourner contre le Fléau. Si la domination nécromancienne de Kel’Thuzad sur ces terres n''était pas si grande, je vous dirais de les détruire complètement !$B$BL''alchimiste Arbington a une liste des composants nécessaires pour ce chaudron (ainsi que pour les autres) afin d''inverser ses effets. Grâce à cela, le temps est venu d''amener le dernier chaudron de l''ouest sous notre influence !', 0),
(5232, 'frFR', 'Ah, il y a plein de choses à étudier, là dedans. Bravo, $N !$B$BLa suite est entre vos mains. Il nous faudra faire une liste des réactifs qui, mélangés au contenu actuel du chaudron, produiront son effet contraire.$B$BLa seule façon d''introduire cela est de placer les réactifs directement dans le chaudron. L''Apothicaire Dithers aura davantage d''informations à ce sujet, parlez-lui donc le plus vite possible.', 0),
(5234, 'frFR', 'Une nouvelle mission réussie, $N ! Cela fait trois chaudrons que nous pourrons retourner contre le Fléau. Si la domination nécromancienne de Kel’Thuzad sur ces terres n''était pas si grande, je vous dirais de les détruire complètement !$B$BL''alchimiste Arbington a une liste des composants nécessaires pour ce chaudron (ainsi que pour les autres) afin d''inverser ses effets. Avec cela, le temps sera venu d''amener le dernier chaudron à l''ouest sous notre influence !', 0),
(5246, 'frFR', 'Les pages sont restées intouchées pendant de très longues années…', 0),
(5247, 'frFR', 'En utilisant ces composants, j''espère pouvoir souder les différents fragments… afin d''en faire ce qu''ils étaient autrefois.', 0),
(5251, 'frFR', 'Extraordinaire, $N ! Des années d''espionnage perdues ! La Croisade écarlate ressentira certainement ce coup dans les semaines qui viennent.', 0),
(5252, 'frFR', 'Est-ce… ce à quoi je pense ?', 0),
(5282, 'frFR', '<Egan essuie une larme. >$B$BAvez-vous vu ma mère, $N ? L''avez-vous libérée ?$B$BVous êtes un brillant exemple d''honnêteté. Pour vous dédommager...', 0),
(5307, 'frFR', 'Il est évident que l''épée est toujours le meilleur choix.', 0),
(5361, 'frFR', 'J''ignore ce qui vous lie à mon frère, mais il semble qu''il ait confiance en vous, $C.$B$BJe suis Nataka Longhorn et je voudrais vous souhaiter la bienvenue au poste de Rôdeur-fantôme, nous avons grand besoin de quelqu''un comme vous, $C ! Parlez avec les autres, il y a certainement quelqu''un ici qui a besoin de votre aide.', 0),
(5461, 'frFR', 'Je doutais de l''existence d''un tel objet. Cela ouvre sans doute d''incroyables opportunités - de celles qu''on ne peut gaspiller.$B$BPréparez-vous, $N, car ce que je vais vous demander va vous projeter dans les entrailles de l''enfer.', 0),
(5462, 'frFR', '<Leonid observe le souvenir de mémoire. >$B$BVotre dilemme me rappelle des souvenirs que j''espérais ne voir jamais ressurgir.', 0),
(5463, 'frFR', 'Vous placez le souvenir de mémoire sur le sol maculé.', 0),
(5464, 'frFR', 'Tout comme l''âme s''est attachée au souvenir de mémoire, elle s''attachera à la forme charnelle de Ras Murmegivre.', 0),
(5465, 'frFR', 'J''étais certain que vous me rejoindriez comme un autre de ces esprits infortunés.', 0),
(5466, 'frFR', 'Dix mille âmes hurlent à l''unisson, $N ! Vous avez porté un coup fatal au Fléau et à ses maîtres.', 0),
(5507, 'frFR', 'Remarquable – ce tribut à l’Aube d''argent est dûment noté, $N. Maintenant que c’est chose faite, je suis enchanté de vous proposer nos mantelets. Tant que vous conserverez votre statut parmi nous, ces mantelets peuvent être achetés auprès de tout quartier-maître de l’Aube d''argent.$B$BPour l’Aube, mon frère !', 0),
(5509, 'frFR', 'Félicitations, $N. Je suis heureux de vous donner une marque de valeur de l''Aube d''argent !$B$BChaque marque de valeur attribuée à un bénéficiaire méritant est un signe que le vent tourne contre le Fléau. Avec un nombre de plus en plus grand de héros combattant le Fléau sur ses propres terres, l''Aube d''argent sera assurément en bonne position quand le temps sera venu de porter l''attaque ultime contre le Fléau. J''espère que la valeur dont vous avez fait preuve pour gagner votre marque fera merveille à nouveau ce jour-là.', 0),
(5510, 'frFR', 'Félicitations, $N - Je suis heureux de vous remettre cette marque de valeur de l''Aube d''argent !$B$BCes marques ont deux usages. Un - elles peuvent être utilisées pour augmenter votre statut au sein de l''Aube d''argent ; elles vous octroient des choix et des récompenses réservés à nos alliés honorés et révérés. Deux - elles peuvent être échangées auprès de nos intendants, avec des pièces, pour obtenir des articles de l''Aube d''argent de grande valeur.$B$BQuoi que vous décidiez, sachez que votre brevet est bien mérité. Bravo !', 0),
(5513, 'frFR', 'Remarquable – ce tribut à l’Aube d''argent est dûment noté, $N. Maintenant que c’est chose faite, je suis enchantée de vous proposer nos mantelets. Tant que vous conserverez votre statut parmi nous, ces mantelets peuvent être achetés auprès de tout quartier-maître de l’Aube d''argent.$B$BPour l’Aube, mon frère !', 0),
(5522, 'frFR', 'Ah, très bien ! Vous ne connaissez pas la puissance maléfique pour laquelle vous avez oeuvré, mais vous allez désormais savoir la vérité. N''ayez crainte, je ne suis pas un serviteur de ce maître. Je suis Leonid Barthalomew, connu comme "le Révéré" par les miens et au sein de l''Aube d''argent.$B$BJ''ai trompé Tinkee en lui faisant vous envoyer à moi avec ces oeufs de dragon. Il est heureux que ma ruse ait fonctionné, car si ces oeufs avaient atteint leur destination prévue, une grande puissance serait tombée aux mains de l''ennemi.', 0),
(5525, 'frFR', 'Vous – vous êtes numéro un. Tous les autres sont numéro deux – ou moins. Merci de m’avoir libéré !$B$BJe savais que j’avais autre chose à faire de ma vie que de servir d’apéritif à un ogre !', 0),
(5529, 'frFR', 'Beau travail, $N ! Ils mettront du temps avant de produire une nouvelle couvée de dragons.$B$B… Du moins je l''espère !', 0),
(5534, 'frFR', 'Ha ha ! Merveilleux !$B$BJe suis sûr de trouver à quoi cela sert et pourquoi la magus Rimtori (c''est la punaise qui m''a embauché) courait derrière. Ha ! Je vous tiens maintenant, sales elfes de sang ! Kim''jael ! Ha ! Je leur apprendrai qui sont les rats !$B$BVous avez bien fait, $N. Merci beaucoup. Voici, prenez cette pièce et laissez-moi, j''ai à réfléchir.', 0),
(5537, 'frFR', 'Ça va marcher, $N ! À mon tour maintenant : je vais les imprégner d''un agent durcissant qui leur permettra de résister au processus intense de forge qu''ils auront à subir.$B$BLa prochaine étape sera de trouver un moule approprié pour la clé. Je connais un forgeron gobelin à Tanaris qui a fait, dans le passé, des moules pour des objets macabres semblables. Il travaille, à l''instar de tous les gobelins, pour celui qui paye le plus.', 0),
(5543, 'frFR', 'Vous êtes un exemple éclatant d''honnêteté, $R ! Il y a bien longtemps que je n''avais senti le sang des héros battre dans mes veines. Vos actes de bravoure nous transportent !', 0),
(5727, 'frFR', 'Excellent ! Simplement excellent, $C !$B$BTout ce que vous avez récemment accompli ne sont que les fondations d''un dessein plus grand, sur lesquelles nous construirons la destruction définitive du Conseil des ombres.$B$BDites-moi tout ce qu''il a dit…et n''omettez pas le moindre mot, il pourrait être plus important que vous ne le croyez.', 0),
(5729, 'frFR', 'Qu''est-ce que c''est ?! Oh, vous, $C... Mes excuses. Ma colère est celle d''un kodo enragé... mais peut-être est-ce de ma faute. En envoyant des voyageurs au gouffre de Ragefeu, j''aurais pu prévoir que des difficultés surviendraient. Il semble que Bazzalan et Jergosh aient été pris par surprise et massacrés par des sbires de Thrall. Tout à fait importun, mais il n''y a rien à faire à cela pour le moment.', 0),
(5801, 'frFR', 'On a bien la coûteuse Clé squelette ici, non, $N ? Enfin, elle est presque finie ; le temps est venu de nous pencher sur la suite. Pour cela, vous allez affronter l''adversaire le plus terrible que nous ayons cherché à rencontrer à Andorhal... Cet être funeste mène la danse derrière les murs de la cité en ruines.$B$BJe veux parler d''Araj l''invocateur - une Liche, et une des plus puissantes entités que le Fléau revendique comme sienne.', 0),
(5802, 'frFR', 'On a bien la coûteuse Clé squelette ici, non $N ? Enfin, elle est presque finie ; le temps est venu de nous pencher sur la suite. Pour cela, vous allez faire face à l''adversaire le plus terrible que nous ayons cherché à rencontrer à Andorhal... cet être funeste mène la danse à l''intérieur des murs de la cité en ruines.$B$BJe veux parler d''Araj l''invocateur - une Liche, et une des plus puissantes entités que le Fléau revendique comme sienne.', 0),
(5805, 'frFR', 'Vous êtes un héros hors du commun, $N. Nous vous souhaitons la bienvenue dans le monde d''Azeroth et vous offrons l''un de ces cadeaux uniques !', 0),
(5841, 'frFR', 'Vous êtes un héros d''exception, $N. Bienvenue dans le monde d''Azeroth, nous vous offrons l''un de ces présents uniques !', 0),
(5843, 'frFR', 'Vous êtes un héros hors du commun, $N. Nous vous souhaitons la bienvenue dans le monde d''Azeroth et vous offrons l''un de ces cadeaux uniques !', 0),
(5861, 'frFR', 'J''étais la plus proche conseillère de Tirion alors qu''il était le seigneur de Mardenholde. J''ai ouvertement contesté le verdict rendu par l''ordre de la Main d''Argent, et je fus bannie pour mon insolence.$B$BIl a connu trop de tragédies de déceptions, $N. Êtes-vous prêt à réparer les torts faits aux Fordring ?', 0),
(5862, 'frFR', 'Quoi, soldat ?$B$B<Taelan ouvre la boîte et examine son contenu. >$B$BCe…ne peut être vrai. Mais tout ce que vous m''avez montré…$B$B<Taelan tombe sur un genou, son pouls s''accélère. La furie du temps est prête à engloutir cette ville. >', 0),
(5882, 'frFR', 'Très bien donc, voici du Baume végétal cénarien. Fouillez Gangrebois pour trouver ces plantes corrompues, $N ! Utilisez ce Baume pour purifier toutes celles que vous trouverez.', 0),
(5883, 'frFR', 'Très bien. Voici plusieurs doses de Baume végétal cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux préparer de baume.', 0),
(5884, 'frFR', 'Excellent travail, $N. Chacune d''elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, $N !', 0),
(5885, 'frFR', 'C''est exactement ce dont j''ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et utilisez-les pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, $N !', 0),
(5886, 'frFR', 'Voilà quelques doses de Baume végétal cénarien. Il ne manque plus qu''une Essence du néant inférieure, $N. Cette essence est de loin l’ingrédient le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !', 0),
(5887, 'frFR', 'Très bien, voici des doses de Baume végétal cénarien. Fouillez Gangrebois à la recherche de toutes les plantes corrompues, $N ! Où qu''elles soient, utilisez le Baume pour les purifier.', 0),
(5888, 'frFR', 'Très bien. Voici plusieurs doses de Baume végétal cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux préparer de baume.', 0),
(5889, 'frFR', 'Excellent travail, $N. Chacune d''elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, $N !', 0),
(5890, 'frFR', 'C''est exactement ce dont j''ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et utilisez-les pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, $N !', 0),
(5891, 'frFR', 'Voilà quelques doses de baume végétal cénarien. Il ne manque plus qu''une essence du néant inférieure, $N. Cette essence est de loin l’ingrédient le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !', 0),
(5892, 'frFR', 'Bien joué ! J''en ferai bon usage. Merci, $N !', 0),
(5893, 'frFR', 'Ah, vous les avez. Bon travail, $N ! Ces fournitures sont un peu moisies d''avoir été stockées dans cette sombre mine si longtemps, mais elles nous seront bien utiles.$B$BMerci, $N. Vos efforts sont d''une importance vitale pour le ravitaillement de nos troupes.', 0),
(5901, 'frFR', 'Cela conviendra parfaitement, $N. Merci.$B$BSi vous le désirez, nous pouvons passer à l''étape suivante.', 0),
(5903, 'frFR', 'Cela conviendra parfaitement, $N. Merci. Regardez-les... Quel triste spectacle. J''ai presque de la pitié pour la Croisade, mais bon, ce n''était pas leur scierie, pas vrai ?', 0),
(5922, 'frFR', 'C''est ainsi que cela commence, Père Cénarius. "$B$BDendrite fait un rapide petit geste invisible au-dessus de lui. Une légère aura de pouvoir se déverse sur lui.$B$B"La première façon de voir la nature à laquelle vous devez vous habituer est celle de l''ours. Je vais vous placer sur la voie afin que vous compreniez cet aspect de la vie d''un $C, mais c''est vous qui devez l''embrasser et la propager, aujourd''hui et à jamais !', 0),
(5923, 'frFR', 'Je suis heureux que vous ayez trouvé votre chemin aujourd''hui, jeune $C. Le temps est venu pour vous de passer à des choses plus sérieuses.$B$BL''appel pour servir la nature est en chacun des enfants de Cénarius. Les animaux et les plantes sont nos amis et nous devons nous en occuper. Nous avons choisi de consacrer notre vie à préserver l''équilibre par égard pour eux autant que pour nous. La première chose que vous devez faire dans ce monde est d''apprendre les voies de l''ours, et d''acquérir la force du corps et du cœur.$B$BPréparez vous !', 0),
(5924, 'frFR', 'Je suis heureux que vous ayez trouvé votre chemin aujourd''hui, jeune $C. Le temps est venu pour vous de passer à des choses plus sérieuses.$B$BL''appel pour servir la nature est en chacun des enfants de Cénarius. Les animaux et les plantes sont nos amis et nous devons nous en occuper. Nous avons choisi de consacrer notre vie à préserver l''équilibre par égard pour eux autant que pour nous. La première chose que vous devez faire dans ce monde est d''apprendre les voies de l''ours, et d''acquérir la force du corps et du cœur.$B$BPréparez vous !', 0),
(5927, 'frFR', 'Je suis heureux que vous ayez trouvé votre chemin aujourd''hui, jeune $C. Le moment est venu pour vous de faire un grand pas dans un monde beaucoup plus vaste.$B$BChacun des enfants de Cenarius porte en lui l''appel à servir la nature. Les animaux et les plantes sont nos amis et nos protégés. Nous choisissons de consacrer notre vie à la préservation de l''équilibre, pour leur bien comme pour le nôtre. Votre premier pas dans ce monde sera d''apprendre les coutumes de l''ours, et d''apprendre la force du corps et du cœur.$B$BPréparez-vous !', 0),
(5929, 'frFR', 'Dendrite fait un autre petit geste rapide et invisible au-dessus de lui lorsque vous vous approchez. Une autre aura de pouvoir se déverse sur lui, et il sourit presque imperceptiblement.$B$B"Je sens de la sagesse en vous, elle n''était pas présente lors de notre première rencontre. Vous me regardez avec force et détermination, mais cette détermination n''est pas encore complètement maîtrisée. Vous allez maintenant apprendre comment concentrer votre force et utiliser la nature de l''ours dans vos actions. "', 0),
(5930, 'frFR', 'Dendrite fait un autre petit geste rapide et invisible au-dessus de lui lorsque vous vous approchez. Une autre aura de pouvoir se déverse sur lui, et il sourit presque imperceptiblement.$B$B"Je sens de la sagesse en vous, elle n''était pas présente lors de notre première rencontre. Vous me regardez avec force et détermination, mais cette détermination n''est pas encore complètement maîtrisée. Vous allez maintenant apprendre comment concentrer votre force et utiliser la nature de l''ours dans vos actions. "', 0),
(5944, 'frFR', 'Le meurtre de mon fils par ces monstres ne restera pas sans conséquences. Que cette nouvelle vous apporte quelque consolation : l''Ordre renaît.$B$BJe prends aujourd’hui ma place de généralissime du nouvel Ordre de la Main d''argent.$B$BEn guise de remerciement, prenez mes anciennes possessions. Elles m''ont été très utiles pendant des années.$B$BNous nous rencontrerons peut-être encore, en des circonstances plus agréables j’espère, et nous nous souviendrons des jours passés... des batailles... des rêves que nous avions.', 0),
(6025, 'frFR', 'Vous l''avez fait, $N ! Merci !$B$BJe vais retourner voir Elling… je veux dire aller à Hurlevent, aussitôt que je le pourrai. Tenez, prenez cette pièce, c''est le moins que je puisse faire pour vous. Vous faites l''honneur de votre peuple, $N. Merci et bonne chance.', 0),
(6026, 'frFR', 'Je peux vous payer la moitié tout de suite et l''autre moitié quand le travail sera fait.', 0),
(6032, 'frFR', 'Ah, très bien ! Cette étoffe lunaire servira à confectionner les vêtements sacrés de notre peuple. Merci, $N. Maintenant je vais vous entraîner.', 0),
(6041, 'frFR', 'Vous êtes beaucoup plus sombre que ce dont je me souvenais. Et vous avez ce regard qui vous trahit ; ce regard qui dit ''je me suis fait carboniser par une bombe. ''$B$B<Rires fumeux. >$B$BQuoi qu''il en soit, voilà votre part du butin. J''ai rajouté un petit extra pour adoucir les brûlures.', 0),
(6066, 'frFR', 'Oui, je crois que vous êtes prêt...', 0),
(6067, 'frFR', 'Oui, je crois que vous êtes prêt...', 0),
(6068, 'frFR', 'Oui, je pense que vous pouvez le faire aussi...', 0),
(6070, 'frFR', 'Oui, il est temps pour vous de commencer votre formation.', 0),
(6073, 'frFR', 'Oui, il est temps, $C.', 0),
(6074, 'frFR', 'Oui, je pense qu''il est temps...', 0),
(6075, 'frFR', 'Oui, je crois que vous êtes prêts, vous aussi....', 0),
(6076, 'frFR', 'Oui, je crois que vous êtes prêts, vous aussi....', 0),
(6145, 'frFR', '<Nathanos rit. >$B$BExcellent ! Enfin ! Une occasion de détruire l''Oracle écarlate !', 0),
(6146, 'frFR', 'Où étiez-vous ? Nous vous pensions entre les mains du Fléau.', 0),
(6147, 'frFR', 'Les imbéciles ! Ma ruse est passée inaperçue ! Préparez-vous, $C. Nous devons frapper avec habileté !', 0),
(6148, 'frFR', 'Ce coup va les faire chanceler pendant des années ! Bien joué, $N ! Vous avez non seulement gagné mon respect mais aussi cette récompense.', 0),
(6163, 'frFR', 'Je me demande... A-t-il imploré grâce ? Savait-il seulement ce que c''est ?$B$B<Nathanos crache. >$B$BJe vais accrocher cette tête sur mon mur.$B$BVous avez gagné votre place parmi mes champions, $N.', 0),
(6187, 'frFR', 'C''est une tragédie. Je pense... je crois que notre espèce est maudite, $N. Nous sommes destinés à perdre tous nos plus grands guerriers, nos plus nobles héros, nos sages les plus avisés.$B$BNous avons une dette envers vous et je vous le promets, $N, où que soit Nathanos Marris maintenant, son sourire est sur vous.', 0),
(6381, 'frFR', 'Que voilà une grande victoire pour nos gens. En temps et en heure, d''autres problèmes passeront d''eux-mêmes : la KapitalRisk rangera ses haches et ses outils, les esprits du feu enragés se calmeront, et les harpies seront chassées de cette terre.$B$BAlors seulement, $N, les Serres-Rocheuses connaîtront vraiment la paix.$B$BVous avez bien agi, $C ; prenez un de ces objets en guise de remerciement.', 0),
(6389, 'frFR', 'Ah ! Merci, $N ! Vous l''avez fait ! L''esprit de mon père est désormais en paix.$B$BMerci encore. S''il y a quoi que ce soit que je peux faire pour vous, je vous en prie, n''hésitez pas.', 0),
(6390, 'frFR', 'Merci, $N. Tenez, prenez cette pièce. Ce n''est pas grand-chose, mais réjouissez-vous d''avoir aidé à annihiler les efforts de la Croisade écarlate !', 0),
(6441, 'frFR', 'C''est parfait, $N ! Merci de votre aide !$B$BOh, et ceci est pour le temps que vous m''avez consacré...', 0),
(6462, 'frFR', 'Vous les avez trouvés ! Merci ! Merci, $N ! Vous ne pouvez pas savoir quel service vous m''avez rendu.$B$BUn troll sans son charme est comme un orc sans cicatrices de combat...$B$BBon à rien.', 0),
(6481, 'frFR', 'Vous apportez de grandes nouvelles, $C ! Je frémis à l’idée de ce qu’un terrestre aurait pu faire subir à Kalimdor.$B$BTuer Goggeroc, voilà un acte digne d’un héros ! Vous avez bien fait, les Serres-Rocheuses et Kalimdor vous sont reconnaissants, noble $C.$B$BAcceptez ceci en récompense.', 0),
(6504, 'frFR', 'La lecture n''est pas mon fort... Mais maintenant je vais pouvoir me remettre au travail ! Merci, $N !', 0),
(6521, 'frFR', 'Bien. Bien joué, $C !$B$BMaintenant que Malcin est mort, nous savons que l''avancée du Fléau sera stoppée. La Dame noire vous remercie pour vos efforts et souhaite vous récompenser.$B$BBien que nous ne connaissions pas l''étendue de l''influence du Fléau dans les Souilles, je suis certain que nous découvrirons leurs plans à temps.', 0),
(6541, 'frFR', 'Orneval est un pays divisé, mais nos récents efforts ont été couronnés de succès. Non seulement nous avons un avant-poste sur la grève de Zoram, mais aussi un autre au nord d''ici, appelé Bois-brisé.', 0),
(6542, 'frFR', 'Orneval est un pays divisé, mais nos récents efforts ont été couronnés de succès. Non seulement nous avons un avant-poste sur la grève de Zoram, mais aussi un autre au nord d''ici, appelé Bois-brisé.', 0),
(6546, 'frFR', 'Apportez mes mises à jour à Kadrak. Rapidement, $N.', 0),
(6547, 'frFR', 'Faisons savoir à Kadrak que nous avons réussi à repousser les elfes de la nuit. Nos plans se déroulent bien.', 0),
(6626, 'frFR', 'Merci, $N ! Le travail que vous avez fait nous sera d''une grande utilité, je le sais.$B$BJe vais continuer mon étude de ce diplomate et des restes des hurans, ici. Si vous cherchez une aventure plus pimentée, trouvez-vous quelques amis et dirigez-vous vers la grotte qui ressemble à une grande gueule de sanglier, par là-bas. Je suis sûr que vous trouverez à l''intérieur des épreuves plus corsées sur lesquelles vous faire les dents.', 0),
(6646, 'frFR', 'Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l''accès aux commerces anciens.', 0),
(6681, 'frFR', 'Excellent, jeune larron.$B$BVous avez l''air d''avoir souffert un peu, mais ce n''est pas terminé.$B$BUn long voyage vous attend – long et enrichissant. Voulez-vous enfin saisir votre chance avec les maîtres de Ravenholdt ?$B$BAdressez-vous aux gardes dehors. Ils vous diront quoi faire.', 0),
(6701, 'frFR', 'Eh ! beau travail. Continuez et les autres voleurs arrêteront peut-être de vous cracher dessus.', 0),
(6827, 'frFR', 'Insuffisant ! Ce genre de travail est correct pour un initié, mais vous, $N ? En avant, soldat, il faut encore de la chair !', 0),
(6845, 'frFR', 'Ah, $N, j''espérais que vous viendriez. J''ai plaisir à vous voir en si bonne forme.$B$BJ''avais entendu dire que vous viendriez et je voulais vous remercier personnellement au nom du Cercle cénarien pour l''aide que vous nous avez apportée jusqu''ici. Il y a sûrement d''autres secrets à découvrir auprès de Silithus ; ce que vous apportez à Umber devrait se monter des plus intéressants. Veuillez accepter ceci en gage de notre reconnaissance.$B$BMerci, généreux $C !', 0),
(6985, 'frFR', 'Vous les avez ! Bien joué, $N ! J''espère que vous avez vu quelques nains pendant votre raid et que vous avez versé leur sang pour les Frostwolf !', 0),
(7002, 'frFR', 'Bon travail, soldat. Je vous dirai quand nous aurons assez de ces peaux.$B$BContinuez !', 0),
(7026, 'frFR', 'Bon travail, soldat. Je vous dirai quand nous aurons assez de ces peaux.$B$BContinuez !', 0),
(7029, 'frFR', 'Merci de m''avoir rapporté ceci, $N. Avec ce qui reste du liquide, je vais pouvoir continuer mes études.$B$BQuoiqu''il reste encore beaucoup à faire, vous m''avez grandement aidé à guérir la corruption que Vylelangue a semée dans Maraudon. Veuillez accepter ceci comme témoignage de ma gratitude.', 0),
(7041, 'frFR', 'Merci de m''avoir rapporté ceci, $N. Avec ce qui reste du liquide, je vais pouvoir continuer mes études.$B$BQuoiqu''il reste encore beaucoup à faire, vous m''avez grandement aidé à guérir la corruption que Vylelangue a semée dans Maraudon. Veuillez accepter ceci comme témoignage de ma gratitude.', 0),
(7064, 'frFR', 'Que voilà de bonnes nouvelles, $N ! Merci !$B$BJe vais parler à Marandis et solliciter son avis éclairé concernant les restes de Zaetar, mais au moins, vous avez fait la plus dure partie du travail.$B$BOn m''a dit que si nous étions victorieux, j''aurais la permission de récompenser ceux qui nous ont apporté leur aide. On m''a remis ces objets à offrir en présents, en gage de reconnaissance de notre peuple ; vous pouvez en choisir un.', 0),
(7065, 'frFR', 'Que voilà de bonnes nouvelles, $N ! Grand merci !$B$BBien que vous n''ayez pas été à même de me ramener les restes de Zaetar, ce qui m''attriste, je ne peux pas me plaindre. Qui serais-je pour remettre en question les décisions du premier-né de Cénarius ? Peut-être que la soif de sang des centaures va désormais se calmer ; nous ne pouvons qu''espérer.$B$BOn m''a remis ces objets, en m''autorisant à en faire don à tout parti nous ayant apporté de l''aide. Vous pouvez en prendre un, en gage de notre gratitude.', 0),
(7067, 'frFR', 'Ça y est, $N ! Ça y est ! Maintenant, je peux me lancer dans la noble tâche consistant à unir les tribus. Merci.$B$BPrenez ceci pour le service rendu, s''il vous plaît. J''espère que notre prochaine rencontre aura lieu sous des auspices plus favorables.', 0),
(7070, 'frFR', 'C''est parfait, $N. En fait, d''autres aventuriers m''aidaient aussi à la tâche, et avec ce qu''ils m''ont ramené, j''ai été capable de fabriquer ces objets... Veuillez accepter l''un d''entre eux en récompense du travail accompli. Et merci encore pour ces échantillons supplémentaires à étudier.', 0),
(7082, 'frFR', 'Bien joué, $N ! Avec ce cimetière sous notre contrôle, les esprits de nos ennemis vont errer, perdus et impuissants…', 0),
(7102, 'frFR', 'J''ai reçu un rapport signalant que vous aviez aidé à saisir une bannière ennemie. Bien joué, $N ! Comme leurs tireurs ne sont plus en position, nous pourrons tenir la zone contre les prochaines attaques de la Horde !', 0),
(7122, 'frFR', 'Vous l’avez fait ! Bravo, $N !$B$BLorsque nous contrôlons une mine et que nous y stationnons des troupes, il est beaucoup plus facile d’y récolter du minerai et du matériel.', 0),
(7123, 'frFR', 'Salut, $N ! Cela fait du bien de voir un $C comme vous, enthousiaste à l''idée de faire sa part pour la Horde. Écoutez-moi bien, car j''ai des tâches d''une importance capitale à vous confier…', 0),
(7163, 'frFR', 'Ce nouvel insigne reflète votre grade parmi les Loups-de-givre. Gardez-le sur vous en permanence.$B$BEt $C... Tâchez de mourir avec honneur !', 0),
(7166, 'frFR', 'Bientôt, tout le champ de bataille sera sous vos yeux vigilants. Vous aurez le commandement de la Vallée et de ses troupes.', 0),
(7167, 'frFR', 'Canalisez le pouvoir de l’insigne. Laissez l’ennemi entendre vos paroles. La puissance de la Horde est incontestable !', 0),
(7169, 'frFR', 'Le roi a été informé de vos exploits sur le champ de bataille, $C. Continuez votre vaillante défense de la Garde Stormpike !', 0),
(7170, 'frFR', 'A notre première rencontre, je ne me serais jamais douté que vous étiez un héros en herbe. Continuez, soldat !', 0),
(7201, 'frFR', 'Merveilleux ! Je vais immédiatement ordonner à un messager de les envoyer à Fossoyeuse !$B$BQuant à vous, voici votre récompense, comme promis. Gardez la monnaie, ignoble bête !', 0),
(7488, 'frFR', 'Vous avez récupéré le filet ! Bien joué, $N ! Leththendris, comme beaucoup d’elfes de son espèce, était aveugle aux dangers que l’excès de magie fait courir à notre monde. Ils croient maîtriser la magie, sans réaliser qu’ils sont esclaves de leur propre dépendance. Sa mort m’attriste, mais elle était nécessaire.$B$BMerci, $N. Je vais faire en sorte que les énergies contenues dans le filet soient dispersées dans une zone assez vaste pour qu’il n’y ait pas de danger, puis je le détruirai pour éviter de nouveaux abus.', 0),
(7498, 'frFR', 'Très bon travail, $R. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.$B$BAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.', 0),
(7501, 'frFR', 'Très bon travail, $R. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.$B$BAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.', 0),
(7504, 'frFR', 'Très bon travail, $R. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.$B$BAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.', 0),
(7506, 'frFR', 'Très bon travail, $R. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.$B$BAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.', 0),
(7604, 'frFR', 'Ce fut un plaisir de faire affaire avec vous, $N !$B$BAu nom de TB Ltd, je vous souhaite bonne chance dans votre recherche de Sulfuras !', 0),
(7632, 'frFR', 'Bien sûr que je reconnais mes propres feuilles. Regardez-la ! Elle est toujours impeccable ! C’est très gentil de me la rendre, $C.$B$BPeut-être pourrons-nous nous rendre mutuellement service.', 0),
(7634, 'frFR', 'Que ces feuilles protégent vos flèches de tout mal. Que vos flèches touchent juste. Que les ennemis de notre monde soient écrasés.', 0),
(7638, 'frFR', 'Je suis content de vous voir, $N. Je sais que vous attendiez depuis longtemps que je vous explique comment vous procurer votre destrier, et le moment est venu.$B$BVous allez affronter de nombreuses épreuves, mais l''essentiel est que vous ayez la volonté de surmonter les obstacles qui vous attendent. Ce n’est pas un exercice – vous avez progressé bien au-delà des simples tests qui ont ponctué votre éducation. Vous devrez arracher votre futur compagnon aux griffes même du mal que vous avez passé votre vie à combattre$B$BÉcoutez bien, car votre heure a sonné !', 0),
(7653, 'frFR', 'Un plaisir de faire des affaires avec vous.$B$BEt $N, cet air dégoûté ne vous va pas.', 0),
(7654, 'frFR', 'Un plaisir de faire des affaires avec vous.$B$BEt $N, cet air dégoûté ne vous va pas.', 0),
(7657, 'frFR', 'Un plaisir de faire des affaires avec vous.$B$BEt $N, cet air dégoûté ne vous va pas.', 0),
(7658, 'frFR', 'Un plaisir de faire des affaires avec vous.$B$BEt $N, cet air dégoûté ne vous va pas.', 0),
(7702, 'frFR', 'Magnifique ! Les Sombrefer vont devoir rentrer chez eux dans les Profondeurs pour se reposer, ce qui va considérablement diminuer la productivité de la Fosse aux scories.', 0),
(7725, 'frFR', 'Absolument fantastique, $N ! Vous avez encore réussi, et je vous en remercie.$B$BMerci !$B$BPeut-être que cette pièce vaut moins que ce à quoi vous êtes habitué, mais soyez assuré que les échos de vos grands exploits pour la gobelinité résonnent aux plus hauts niveaux du Cartel Gentepression. Si vous cherchez quelque chose d''autre à faire, surtout venez me parler !', 0),
(7730, 'frFR', 'Bien joué, $C. Bien qu''on ne puisse lutter contre l''étendue de la présence des Zukk''ash que par une invasion à grande échelle, vous nous offrez du temps pour mettre en place une véritable stratégie.$B$BJe vais faire analyser ces carapaces : nous devons tout apprendre à leur sujet avant de nous occuper de ce problème qui s''avère bien plus délicat que prévu.', 0),
(7735, 'frFR', 'Incroyable ! Vous avez trouvé LA peau de yéti !$B$BJe suis prêt à la payer au prix fort. Normalement, pour une seule peau, je ne donne pas autant, mais je suis sûr que je pourrai faire quelque chose d’extraordinaire avec celle-là. Merci d’avoir pensé à moi, $N !', 0),
(7736, 'frFR', 'Il y a toujours de la place pour plus de flux embrasé, junior. Continuez comme ça... Jusqu''à ce que je vous dise d''arrêter.', 0),
(7738, 'frFR', 'C’est une trouvaille incroyable ! Je crois bien que c’est la plus belle peau de yéti que j’aie jamais vu !$B$BCela mérite une récompense de choix. Normalement, pour une seule peau, je ne donne pas autant, mais je suis sûr que je pourrai faire quelque chose d’extraordinaire avec celle-là. Merci d’avoir pensé à moi, $N !', 0),
(7791, 'frFR', 'Merveilleux ! Nous vous remercions pour votre généreux don, $N !', 0),
(7792, 'frFR', 'Nous vous remercions pour ce don, $N.', 0),
(7793, 'frFR', 'Merveilleux ! Nous vous remercions pour votre généreux don, $N !', 0),
(7794, 'frFR', 'Merveilleux ! Nous vous remercions pour votre généreux don, $N !', 0),
(7795, 'frFR', 'Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.$B$BComme vous avez déjà contribué, je traiterai en priorité tous les dons d''étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !', 0),
(7796, 'frFR', '$N, l’avenir serait compromis sans des héroïnes comme vous qui œuvrent pour Stormwind. Merci de tous vos efforts !', 0),
(7798, 'frFR', 'Nous vous remercions pour votre don, $N.', 0),
(7799, 'frFR', 'Merveilleux ! Nous vous remercions pour votre généreux don, $N !', 0),
(7800, 'frFR', 'Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.$B$BComme vous avez déjà contribué, je traiterai en priorité tous les dons d''étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !', 0),
